// tools/gen_lines.py 가 생성 — 원작 로비 대사 (t: 대사, v: 보이스 이벤트, c: 사령관을 직접 부름)
const LAO_LINES = {"3P_ConstantiaS2":[{"t":"오늘은 어떤 차가 좋을까요?","v":"Idle_01_01","c":0},{"t":"정말… 심심하신 모양인데, 어떡한다?","v":"Idle_01_02","c":0},{"t":"이렇게 날씨가 좋은 날은 도시락을 싸서 소풍을 가고 싶네요.","v":"Idle_01_03","c":0},{"t":"맛있는 차는 좋은 찻잎, 좋은 물, 그리고 애정이 필요해요.","v":"Idle_02_01","c":0},{"t":"평화로워지면 소풍을 가요. 둘이서만… 다른 사람들은 없는 곳으로요.","v":"Idle_03_01","c":0},{"t":"… 말씀만 하시면… 주인님을 즐겁게 하는 것도 임무니까요.","v":"Idle_04_01","c":1}],"BR_PA00EL":[{"t":"되도록 들러붙진 말아줘. 나 끈적한 거 질색이거든?","v":"Idle_01_01","c":0},{"t":"혹시 착각할 까봐 말하는데 인간을 보고 있는 건 그냥 임무라서야. 다른 뜻은 없다고.","v":"Idle_01_02","c":0},{"t":"뭐? 이 전투 수트? 별로. 이건 속옷이나 수영복 아니거든? 전혀 부끄럽지 않은데?","v":"Idle_01_03","c":0},{"t":"들러붙지 말란 뜻이 저리 가란 뜻은 아니거든? 뭐… 0.5미터 정도로 봐줄게.","v":"Idle_02_01","c":0},{"t":"뭐야? 엉큼하게. 혹시… 관심이라도 있는 거야? 흐흥… 그렇다면 어쩔 수 없지만...","v":"Idle_03_01","c":0},{"t":"내가 언제 인간을 봤다고 그래? 아니거든? 완전 착각이거든?","v":"Idle_04_01","c":0}],"DS_Johanna":[{"t":"주군이 원한다면 과거의 기사들에 대한 이야기를 해줄 수 있다네.","v":"Idle_01_01","c":1},{"t":"내 검은 주군에게 맡긴 걸세. 그 의미를 잊지 않도록 하게나.","v":"Idle_01_02","c":1},{"t":"요즘은 훈련과 전투 외엔 할 일이 없군. 예전엔 좀 더 과거의 영광에 대해 이야기할 시간이 있었는데 말이야.","v":"Idle_01_03","c":0},{"t":"주군에겐 할 말이 참 많다네. 그 수많은 이야기를 어떻게 다 할 수 있겠나?","v":"Idle_02_01","c":1},{"t":"가끔씩은 훈련과 전투 외에 주군과 이야길 하고 싶다네. 주군, 나와 이야길 해주겠나?","v":"Idle_03_01","c":1},{"t":"내 검은 오직 주군을 위해 존재할 걸세. 영원히.","v":"Idle_04_01","c":1}],"PECS_PuppHead":[{"t":"자, 내 멋진 강철제 보디를 보게나. 칭찬해도 좋네.","v":"Idle_01_01","c":0},{"t":"개라니! 무례하군. 6급 공무원이라고 말하지 않았나?","v":"Idle_01_02","c":0},{"t":"사실 난 진짜 몸을 가지고 있다네. 언젠간 그 몸을 되찾았으면 좋겠군.","v":"Idle_01_03","c":0}],"AGS_Fallen":[{"t":"AGS 로보 테크는 인류 보호를 위해 만들어졌습니다!","v":"Idle_01_01","c":0},{"t":"(알 수 없는 기계음)","v":null,"c":0},{"t":"무엇을 도와드릴까요?","v":"Idle_01_03","c":0}],"PECS_LRL":[{"t":"왜 그...? 아, 아니… 무슨 일인가? 인간?","v":"Idle_01_01","c":0},{"t":"후. 후. 후. 짐의 사안에 봉인된 파멸의 멸절을 느낀 건가?","v":"Idle_01_02","c":0},{"t":"훗. 이 몸과 함께하길 원하나? 그렇다면... 그에 걸맞는 자격을 갖추고 오도록!","v":"Idle_01_03","c":0},{"t":"쯧. 쯧. 경비가 허술하군. 그대의 참치는 모조리! ...히잉! 갖다 놓을게… 미안해…","v":"Idle_02_01","c":0},{"t":"인간, 혹시 불멸을 원한다면 말하도록 해라. 그대와는 이 거대한 힘을 나눌 생각이니.","v":"Idle_03_01","c":0},{"t":"유구의 세월을 기다렸다. 드디어, 짐을 인정해 주는 자를 만났으니! ...고마워, 사령관. 히히~.","v":"Idle_04_01","c":1}],"3P_Labiata":[{"t":"자, 사령관답게 복장을 단정히 하셔야죠?","v":"Idle_01_01","c":1},{"t":"참… 어딜 보시는 거예요?","v":"Idle_01_02","c":0},{"t":"너무 걱정 마세요. 제가 있으니까요.","v":"Idle_01_03","c":0},{"t":"어머, 옷에 주름이 갔네요. 자, 잠깐만 가만히 계셔 보세요.","v":"Idle_02_01","c":0},{"t":"언제 어디서든지 제가 꼭 지켜 드릴게요.","v":"Idle_03_01","c":0},{"t":"그렇게 보셔도… 으… 안 돼요! 그렇게 보시면.","v":"Idle_04_01","c":0}],"PECS_Drone":[{"t":"무엇을 도와드릴까요?","v":"Idle_01_01","c":0},{"t":"제 임무는 공중 수송에 특화되어 있습니다.","v":"Idle_01_02","c":0},{"t":"PECS 사는 시민 여러분의 친구입니다. 24시간 콜 서비스를 잊지 마세요!","v":"Idle_01_03","c":0}],"BR_Amy":[{"t":"어째서 그런 눈으로 보는 거죠? 후후... 설마?","v":"Idle_01_01","c":0},{"t":"가끔씩은 제 뜻을 알아주지 못하는 아이들이 있어서 힘이 드네요.","v":"Idle_01_02","c":0},{"t":"제가 다른 아이들을 재워주는 거요? 후후, 자기도 재워줄 사람이 필요한가요?","v":"Idle_01_03","c":0},{"t":"자기, 어젯밤은 즐거웠나요? 응? 왜 얼굴이 빨개지죠?","v":"Idle_02_01","c":0},{"t":"네네. 자장가를 불러드릴 테니 제 옆에 누워보시겠어요?","v":"Idle_03_01","c":0},{"t":"어때요? 제 마음을 알아주는 아이들을 함께 교육하겠어요?","v":"Idle_04_01","c":0}],"PECS_CoCoWhiteShell":[{"t":"사령관님을 만나게 돼서 다행이에요. 아무리 그래도 화성보단 지구가 좋거든요?","v":"Idle_01_01","c":1},{"t":"화이트 쉘을 타고 바다를 탐험하는 것도 기분 좋은 일이에요.","v":"Idle_01_02","c":0},{"t":"음… 어른이 되곤 싶은데 몸이 커져서 화이트 쉘을 타지 못하는 건 싫어요.","v":"Idle_01_03","c":0},{"t":"지구에 있어서 좋은 점이요? 헤헤. 사령관님이랑 같이 있을 수 있는 거요?","v":"Idle_02_01","c":1},{"t":"웅… 전 어른이 될 수 있는 걸까요? 어른이 되지 못하면 사령관님은 절 아이로만 보시겠죠?","v":"Idle_03_01","c":1},{"t":"사령관님이 조금만 더 작으셨으면 화이트 쉘에 같이 탈 수 있었을 텐데… 너무 아쉬워요.","v":"Idle_04_01","c":1}],"BR_Marie":[{"t":"평소에 말입니까? 주로 훈련이나 명상에 시간을 씁니다만?","v":"Idle_01_01","c":0},{"t":"전투에서 가장 중요한 건 의지입니다. 승리하겠단 의지만 있다면 어떻게든 이겨낼 수 있습니다.","v":"Idle_01_02","c":0},{"t":"좋아하는 것 말입니까? 당연히 훈련과 군사학입니다만? 커피요? 그저 잠이 오지 않게 마시는 것에 불과합니다.","v":"Idle_01_03","c":0},{"t":"요즘은 훈련에 힘을 더 많이 씁니다. 아무래도… 명상에 잡념이 많아져서....","v":"Idle_02_01","c":0},{"t":"코피루왁? 에스메랄다 게이샤? 무, 무슨 말씀을 하시는지… 전 그런 거 잘 모릅니다만… … 설마 정말 그걸 구하신 건 아니시겠죠? 설마… 구하셨습니까?","v":"Idle_03_01","c":0},{"t":"과거엔 누굴 위해 승리해야 하는가에 대해 고민했었습니다만… 이젠 고민이 사라졌습니다.","v":"Idle_04_01","c":0}],"PECS_MissSafety":[{"t":"언젠가는 평화로운 날이 왔으면 좋겠습니다.","v":"Idle_01_01","c":0},{"t":"걱정 마십시오. 이곳의 안전은 언제나 제가 감시하고 있습니다.","v":"Idle_01_02","c":0},{"t":"저도 되도록 총탄보다는 경찰봉을 사용하고 싶습니다만… 이젠 그런 범죄자들이 없군요.","v":"Idle_01_03","c":0},{"t":"거리가 평화로워지면… 사령관님께 데이트 신청을 하고 싶군요.","v":"Idle_02_01","c":1},{"t":"후후. 경찰봉엔 여러 가지 용도가 있습니다. 예를 들어 사령관님께 사용을 한다거나요.","v":"Idle_03_01","c":1},{"t":"걱정 마십시오. 여긴 아무도 없습니다. 그러니… 조금쯤 욕심을 채워도 된다는 말입니다.","v":"Idle_04_01","c":0}],"BR_Brownie":[{"t":"아, 이렇게 작업 없는 날이 좋지 말입니다.","v":"Idle_01_01","c":0},{"t":"응? 헤헤. 역시 군인은 노래지 말임다.","v":"Idle_01_02","c":0},{"t":"우리 근데 MRE는 좀 개선 안 하는 검까? 스팸이 부족하지 말입니다.","v":"Idle_01_03","c":0},{"t":"지금은 작업이 없슴다. 헤헤… 우리 재밌는 거라도 좀 하지 말임다.","v":"Idle_02_01","c":0},{"t":"따로 좀 챙겨둔 스팸이 있슴다. 헤헤. 같이 먹지 말임다.","v":"Idle_03_01","c":0},{"t":"노래는 연습해 둘 생각임다. 그… 이전 세상에선 노래방이란 데가 있어서… 둘이 같이 가기도 했다고 들어서 말임다.","v":"Idle_04_01","c":0}],"PECS_MightyR":[{"t":"자, 그렇게 있지만 말고. 저랑 운동이라도 하실래요?","v":"Idle_01_01","c":0},{"t":"가끔씩은… 이걸 왜 하고 있나 싶지만. 샤워하고 나면, 잘 하고 있구나 싶어요.","v":"Idle_01_02","c":0},{"t":"어느 쪽이냐면, 튼튼한 쪽이 더 좋죠 걱정 마요. 제가 다 알아서 해줄게요.","v":"Idle_01_03","c":0},{"t":"실력 좋네요. 계속 그렇게만 해주세요. 걱정 마요, 사령관님은 충분히 잘하고 있으니까요.","v":"Idle_02_01","c":1},{"t":"사령관 님? 제가 사령관님의 자세를 조금 봐 드려도 될까요? 힘… 빼 시라구요.","v":"Idle_03_01","c":1},{"t":"사령관님? 그렇게 훔쳐보실 필요 없어요. 그런 관심은… 저도 싫지 않거든요.","v":"Idle_04_01","c":1}],"PECS_DutchGirl":[{"t":"아무래도 좋아. 그냥 지금은 달콤한 거나 하나 먹었으면 좋겠네…","v":"Idle_01_01","c":0},{"t":"바다 밑에 있는 게 땅 밑에 있는 것보다는 나아. 적어도 여긴 햇빛은 들어오잖아.","v":"Idle_01_02","c":0},{"t":"사령관은 가끔씩 거짓말을 진짜처럼 해. 좋은 날이 올 거라니… 그럴 리 없잖아.","v":"Idle_01_03","c":1},{"t":"사령관이 있어줘서. 힘이 나는 것 같아. 고마워... 사령관.","v":"Idle_02_01","c":1},{"t":"사령관이 이야기해줬지? 좋은 날이 온다고.... 그 말... 믿어도 될까?","v":"Idle_03_01","c":1},{"t":"나도... 조금 꾸미면… 괜찮아질 수 있을까? ...안되겠지?","v":"Idle_04_01","c":0}],"3P_Daphne":[{"t":"화창한 날이에요. 이런 날엔 숲속을 걷고 싶습니다.","v":"Idle_01_01","c":0},{"t":"잠수복이 있다면 바다 정원을 만들 수 있을 텐데요.","v":"Idle_01_02","c":0},{"t":"리제 언니 일은… 죄송해요. 언니가 조금 집중력이 좋은 편이라…","v":"Idle_01_03","c":0},{"t":"이렇게 날씨가 좋으면… 주인님과 숲속을 거닐고 싶어요.","v":"Idle_02_01","c":1},{"t":"… 집착하지 않는다고 해서 언니보다 주인님을 생각하는 마음이 적은 건 아니에요.","v":"Idle_03_01","c":1},{"t":"바다 정원을 만들고… 거기에 우리의 집을 짓고 싶어요.","v":"Idle_04_01","c":0}],"AGS_Albatross":[{"t":"너무 싸움을 피하는 것 아닌가?","v":"Idle_01_01","c":0},{"t":"충분한 정보를 얻은 후엔 싸워야 하지.","v":"Idle_01_02","c":0},{"t":"방공, 방호, 정찰, 급유 등 내겐 모든 임무가 가능하지.","v":"Idle_01_03","c":0}],"PECS_TommyWalker":[{"t":"PECS 사는 시민 여러분의 친구입니다. 24시간 콜 서비스를 잊지 마세요!","v":"Idle_01_01","c":0},{"t":"정확한 명령 필요.","v":"Idle_01_02","c":0},{"t":"토미 워커 : 목적 - 통상적 수송, 파괴 임무에 특화되어 있음.","v":"Idle_01_03","c":0}],"PECS_Fortune":[{"t":"후후, 이 누나도 사령관이랑 이야기하고 싶었거든.","v":"Idle_01_01","c":1},{"t":"기계에 관한 건 누나한테 맡기면 돼. 누나 완전 전문가 거든?","v":"Idle_01_02","c":0},{"t":"사령관이랑 있으면, 시간이 너무 잘 가서 아쉽거든…","v":"Idle_01_03","c":1},{"t":"사령관은… 누나하고 그냥 이야기만 하고 싶었던 거야? 아니면…","v":"Idle_02_01","c":1},{"t":"우리 사령관… 누나가 무릎베개라도 해줄까? 후후.","v":"Idle_03_01","c":1},{"t":"누나랑 있을 땐 긴장 풀어도 되거든? 그래도 너무 늘어져 있으면. 누나가 장난치고 싶어져.","v":"Idle_04_01","c":0}],"BR_Leprechaun":[{"t":"각하, 전, 각하가 브라우니 수준으로 떨어지지 않길 바랍니다.","v":"Idle_01_01","c":1},{"t":"되도록 자리를 지켜 주십시오. 무슨 소리입니까? 업무 지원을 위해섭니다.","v":"Idle_01_02","c":0},{"t":"딱히 각하를 보고 있는 건 아닙니다만… 무슨 소리십니까? 착각입니다.","v":"Idle_01_03","c":1},{"t":"바보를 살리는 게 제 일이죠. 아이들이 조금만 조심해 주면 좋을 텐데요.","v":"Idle_02_01","c":0},{"t":"그렇게 지긋이 보는 건 관둬 주세요. 이 방에 둘이만 있는 걸로도… 충분히 부담스럽습니다.","v":"Idle_03_01","c":0},{"t":"네, 가까이… 업무 지원을 좀 더 쉽게 하기 위해서… 그냥 그것 뿐입니다.","v":"Idle_04_01","c":0}],"3P_Fotia":[{"t":"조, 조금만 물러나 주세요… 아직 냉각이 덜 됐으니까요.","v":"Idle_01_01","c":0},{"t":"요리요? 아… 불을 쓰는 요리라면 문제없어요.","v":"Idle_01_02","c":0},{"t":"헤헤. 소풍이나 야외 바비큐 파티를 할 수 있는 날이 오면 좋겠어요.","v":"Idle_01_03","c":0},{"t":"잠시만요. 주인님, 조심하셔야 해요. 주인님은 다치시면 안 돼요.","v":"Idle_02_01","c":1},{"t":"전, 바비큐가 특기예요. 원하시면 지금이라도 보여 드릴 수 있어요. 헤헤.","v":"Idle_03_01","c":0},{"t":"언젠간 주인님만을 위해 요리하고 싶어요.","v":"Idle_04_01","c":1}],"3P_ScissorsLise":[{"t":"후후… 주인님과 둘이라니… 시간이 멈췄으면…","v":"Idle_01_01","c":1},{"t":"걱정 마세요. 이 시간을 방해하지 못하도록 문은 잠가 놨으니…","v":"Idle_01_02","c":0},{"t":"아까, 다른 아이를 보고 웃는 걸 봤어요… 설마… 제 착각이겠죠?","v":"Idle_01_03","c":0},{"t":"시간이 멈췄으면 좋겠어요. 아니면… 시간을 느끼는 감각이 파괴되어도 좋고요","v":"Idle_02_01","c":0},{"t":"괜찮아요. 주인님은 아무 잘못 없어요. 주인님의 눈을 어지럽히는 아이들의 잘못이죠.","v":"Idle_03_01","c":1},{"t":"차라리 잠수함 바깥에 요새를 지으면 좋겠어요. 나머지 애들을 거기에...","v":"Idle_04_01","c":0}],"BR_PoniesAnger":[{"t":"가끔씩 옛날 슈퍼 히어로 영활 보거든! 아, 나도 잘 할 수 있을 것 같은데…","v":"Idle_01_01","c":0},{"t":"심심하면 철충들 기록을 정리해. 누가 제일 나쁜 놈인지 알아야 하니까.","v":"Idle_01_02","c":0},{"t":"사실 군인보단 경찰 쪽이 적성에 맞는데… 뭐 이런 세상에선 마찬가진가?","v":"Idle_01_03","c":0},{"t":"헤헤. 나중에 사령관 덕분에 내가 히어로라고 불리는 날이 분명히 올 거야.","v":"Idle_02_01","c":1},{"t":"사령관, 나 사령관을 위해서 나쁜 놈들을 잡는 게 좋아. 아, 물론 사령관이 아니라도 좋아하는 일이긴 하지만...","v":"Idle_03_01","c":1},{"t":"사령관, 우리 2인조 히어로로 활동할까? 내가 사이드킥을 해도 되니까...","v":"Idle_04_01","c":1}],"BR_AS12TurtleDragon":[{"t":"이렇게 앉아 있으면 뭘 해? 운동이라도 하자고!","v":"Idle_01_01","c":0},{"t":"좋아하는 것? 흐음… 몰라! 그냥 땀이 나 빼는 거 정도? 아! 고기! 고기 좋지!","v":"Idle_01_02","c":0},{"t":"사령관, 뭔가 눈이 음흉한데… 어딜 보는 거야? 서, 설마...","v":"Idle_01_03","c":1},{"t":"운동 좋지. 사령관, 같이 할래?","v":"Idle_02_01","c":1},{"t":"사령관, 그렇게 보면 달려들고 싶거든? 긍정적인 의미로 말이야.","v":"Idle_03_01","c":1},{"t":"히히. 사령관, 우리 같이 땀이라도 뺄까? 응?","v":"Idle_04_01","c":1}],"BR_Nereid":[{"t":"친구들이랑 놀 생각을 하면 늘 즐겁단 말이지.","v":"Idle_01_01","c":0},{"t":"장난이 심하다고? 아냐. 모두 즐거워하니까 네리가 나서는 거야!","v":"Idle_01_02","c":0},{"t":"뭐 미니건은 배 위에서나 땅에서나 잘 나가니까… 딱히 땅에서 싸우는 건 상관없어!","v":"Idle_01_03","c":0},{"t":"요즘은 사령관이랑 노는 게 제일 좋으려나?","v":"Idle_02_01","c":1},{"t":"이렇게 밀폐된 곳에서 둘이만 있으니… 못된 장난을 치고 싶어져.","v":"Idle_03_01","c":0},{"t":"사령관, 사령관, 내가 즐겁게 해줄까? 히히, 맡겨 두라구!","v":"Idle_04_01","c":1}],"3P_CSPerrault":[{"t":"밖이 좀 소란스럽네요… 조용하게 만들까요?","v":"Idle_01_01","c":0},{"t":"오늘의 스케줄 목록입니다. 변경하실 사항이 있으시면 알려주세요.","v":"Idle_01_02","c":0},{"t":"옷 장식이 아니니 당기지 말아 주세요...","v":"Idle_01_03","c":0},{"t":"그리폰과 LRL을 침묵 시켰습니다. 어떻게 했냐구요…? … 비밀입니다.","v":"Idle_02_01","c":0},{"t":"쓰다듬으시는 건 상관없지만…슬슬 일을 해야 하지 않을까요...","v":"Idle_03_01","c":0},{"t":"네…? 아... 뭐가 묻으신 것 같아서 청소 중이었습니다.","v":"Idle_04_01","c":0}],"PECS_Tiequan":[{"t":"주인, 오늘 내 모습은 어땠어? 칭찬할 일 없어?","v":"Idle_01_01","c":0},{"t":"뭐든지 맡겨 두라고! 이 몸에게 어려운 건 없거든?","v":"Idle_01_02","c":0},{"t":"주인, 약간 자세가 어정쩡하네? 선물 같은 거 있으면 얼른 줘. 부끄러워할 거 없어!","v":"Idle_01_03","c":0},{"t":"여기 좀 만져봐 사령관, 나 요즘 살이 좀 찐 것 같은데… 괜찮을까?","v":"Idle_02_01","c":1},{"t":"자세가 왜 그렇게 구부정해? 내가 고쳐줄 테니까. 가만히 있어봐. 가, 가만히 있으래도?!","v":"Idle_03_01","c":0},{"t":"흐응~ 주인과 함께 있으면, 출세랑은 자꾸 거리가 멀어지는 것 같단 말이지. 뭐… 그렇게 싫진 않아.","v":"Idle_04_01","c":0}],"BR_BeastHunter":[{"t":"어떤 장갑이든 내 포 앞에서 무사한 건 없죠.","v":"Idle_01_01","c":0},{"t":"기분 좋은 일? 전 강하고 큰 적이 제 앞에 쓰러질 때 가장 기분이 좋죠.","v":"Idle_01_02","c":0},{"t":"걱정 마세요. 싸울 때 이외엔 부드러운 여자니까.","v":"Idle_01_03","c":0},{"t":"그러고 보면, 사령관도 포를… 아니… 미안해요. 이 농담은 안 할걸 그랬어요.","v":"Idle_02_01","c":1},{"t":"원하신다면 언제든지 제가 얼마나 부드러운 사람인지를 증명할 수 있어요.","v":"Idle_03_01","c":0},{"t":"후후… 사령관, 어쩌면 오늘 제가 사령관을 함락하러 갈 수도?","v":"Idle_04_01","c":1}],"BR_Emily":[{"t":"사령관…나 아직 모르는 게 많아서 많이 배우고 싶어.","v":"Idle_01_01","c":1},{"t":"사령관, 농담 같은 거 알아…? 가르쳐 줘… 다른 동료들에게 해볼래...","v":"Idle_01_02","c":1},{"t":"이 옷…? 정식 모델이 아니어서… 적당히 맞는 걸 입어…이상해...?","v":"Idle_01_03","c":0},{"t":"사령관 침대 밑에서 책을 찾았어. 콘스탄차가 난 보면 안 되는 거라던데... 왜 안돼?","v":"Idle_02_01","c":1},{"t":"이동할 때 제녹스 위에 타면 편해… 헌터가 보면 혼내지만... 사령관도 타볼래...?","v":"Idle_03_01","c":1},{"t":"사령관한테 배운 농담… 자매들이 재미없댔어… 난 재밌는 거 같은데...","v":"Idle_04_01","c":1}],"BR_Phantom":[{"t":"음… 혼자여도 좋으니, 작은 동물 친구라도 함께 해줬으면 하는 생각도 해요.","v":"Idle_01_01","c":0},{"t":"역시 외톨이인 건… 말재주가 없어서일까요? 아, 이런 고민은 비밀입니다.","v":"Idle_01_02","c":0},{"t":"표정이라면... 주위에서 의지할 수 있는 사람이 되기 위해 근엄한 표정을 유지합니다만...","v":"Idle_01_03","c":0},{"t":"역시… 동물보단… 사령관이랑 있는 게… 아! 아닙니다.","v":"Idle_02_01","c":1},{"t":"이상합니다. 왜 사령관 앞에선 표정이 풀려 버리는 걸까요?","v":"Idle_03_01","c":1},{"t":"음… 지금은 아무래도 좋아요. 그냥… 사령관이 옆에 있기만 하다면...","v":"Idle_04_01","c":1}],"BR_Tomoe":[{"t":"내 매력? 역시… 학생다운 노력과 그에 따르는 지성미?","v":"Idle_01_01","c":0},{"t":"학교에 숨어 있는 거? 뭐… 옛날엔 학교에 납치나 그런 게 많았다던데?","v":"Idle_01_02","c":0},{"t":"그… 뭐였더라? 나처럼 다방면으로 괜찮은 애를 말하는 거… 그 '미인방면'이었나?","v":"Idle_01_03","c":0},{"t":"사령관, 끝말잇기라도 할래? 내 지성미를 느낄 수 있게 말이야.","v":"Idle_02_01","c":1},{"t":"알아. 사령관 내 '미인박명'적인 모습에 확 반한 거지? 훗! 뭐 내 지성과 미모는 비례하는 거니까.","v":"Idle_03_01","c":1},{"t":"사령관, 걱정 마. 내가 항상 옆에서 지켜줄 테니까.","v":"Idle_04_01","c":1}],"BR_BloodyPanther":[{"t":"군대는 체질이니, 걱정하지 않으셔도 됩니다.","v":"Idle_01_01","c":0},{"t":"너무 빡빡하게 구는 건 아닙니다~. 원래 군대가 이런 데지 말입니다~?","v":"Idle_01_02","c":0},{"t":"애들이 좀 빠져 있긴 합니다. 제대로 가르쳐야 합니다.","v":"Idle_01_03","c":0},{"t":"음… 사령관님이 상사면… 저 말뚝 박고 싶지 말입니다.","v":"Idle_02_01","c":1},{"t":"절 리더로 삼아 주시면, 애들을 확 휘어잡아서 사령관 님께 순종하게 만들지 말입니다.","v":"Idle_03_01","c":1},{"t":"자꾸 저한테 느슨하게 굴지 말아 주십쇼. 자꾸 마음이 약해지면 군기가 빠지지 말입니다...","v":"Idle_04_01","c":0}],"BR_Io":[{"t":"… 제가 이런 큰 기계를 책임져도 될지… 걱정될 때가 있어요.","v":"Idle_01_01","c":0},{"t":"그, 그래도 시키는 건 열심히 하는 편이에요. 버리지 말아 주세요...","v":"Idle_01_02","c":0},{"t":"무섭지만… 그렇다고 도망만 갈 수는 없는 거니까...","v":"Idle_01_03","c":0},{"t":"저한테... 이런 장갑 유닛을 주신 이유는 잘 모르겠지만… 열심히 해서 보답할게요.","v":"Idle_02_01","c":0},{"t":"사령관님이 옆에 있어 주신다면… 저 겁내지 않을 수 있어요.","v":"Idle_03_01","c":1},{"t":"사령관님이 시키는 건 뭐든지 열심히 할 수 있으니까… 그러니까 항상 함께 있어 주세요!","v":"Idle_04_01","c":1}],"BR_Valkyrie":[{"t":"딱히 잡담은 관심 없습니다.","v":"Idle_01_01","c":0},{"t":"스코프는 생존율을 낮출 뿐입니다. 차라리 조용히 가까이 가는 게 도움이 됩니다.","v":"Idle_01_02","c":0},{"t":"좋아하는 건… 딱히 없습니다만.","v":"Idle_01_03","c":0},{"t":"… 가끔씩은 이렇게 이야기를 하는 것도 나쁘진 않겠군요...","v":"Idle_02_01","c":0},{"t":"최근엔 좋아하는 ... 생겼습니다. 음… 다음에… 말씀드리겠습니다.","v":"Idle_03_01","c":0},{"t":"제 개조된 눈에 감사할 때가 있습니다. … 지휘관 각하를 조금 더 자세히 볼 수 있으니까요.","v":"Idle_04_01","c":1}],"BR_NightAngel":[{"t":"가끔씩 메이 대장을 보면 과연 대장이다 싶을 때가 있긴 해요. 특히 그 상체.","v":"Idle_01_01","c":0},{"t":"흉부 지방은 스텔스 기능과 비행에 방해만 됩니다.","v":"Idle_01_02","c":0},{"t":"이 제복이 마음에 들진 않아요. 뭐랄까… 왜 굳이 흉부 쪽이 트인 거죠?","v":"Idle_01_03","c":0},{"t":"쳇. 메이 꼬맹이의 가슴은 나 같은 어른에게 어울리는데...","v":"Idle_02_01","c":0},{"t":"가슴 트임… 칫! 끌어모으는 것도 밑천이 있어야 가능한 겁니다만?","v":"Idle_03_01","c":0},{"t":"가끔씩은 스텔스 기능 따윈 개나 주고 싶습니다.","v":"Idle_04_01","c":0}],"PECS_Cerberus":[{"t":"가만히 있으려니 좀 심심한데… 산책이라도 할까요?","v":"Idle_01_01","c":0},{"t":"뭔가 재미있는 건 없을까요? 이럴 때 철충이라도 나타나 주면 좋을 텐데요…","v":"Idle_01_02","c":0},{"t":"심심해요. 심심해! 사령관님, 우리 재미있는 거 좀 없을까요?","v":"Idle_01_03","c":1},{"t":"사령관님, 사령관님, 우리 복도라도 같이 다녀요. 네? 그럼 안 돼요?","v":"Idle_02_01","c":1},{"t":"사령관님이랑 있으면 심심하긴 해도 행복해져요. 음… 헷. 말로는 못하겠어요.","v":"Idle_03_01","c":1},{"t":"히히. 나중에 세상이 평화로워지면 사령관님이랑 잔뜩 데이트할 거예요.","v":"Idle_04_01","c":1}],"BR_May":[{"t":"사령관, 난 전쟁이 좋아. 빨리 적을 찾아오도록 해.","v":"Idle_01_01","c":1},{"t":"내 머리 위의 무기? 흠… 말해도 될까? 좀 위험한 무기인데?","v":"Idle_01_02","c":0},{"t":"뭐니 뭐니 해도 결국 전쟁은 폭격으로 결판나는 거야. 무식하게 몸으로만 뛰는 칸 녀석은 모르겠지만.","v":"Idle_01_03","c":0},{"t":"약간 고민이 되는걸? 사령관과 전쟁 중 어느 쪽이 더 좋은지…","v":"Idle_02_01","c":1},{"t":"언젠간 사령관에게 내가 최고란 걸 증명해 줄게. 다른 지휘관들은 사실 사령관한테 필요 없어.","v":"Idle_03_01","c":1},{"t":"내 무기는 잘 알고 있겠지? 오늘은 사령관의 무기를 확인하고 싶은데?","v":"Idle_04_01","c":1}],"BR_Efreeti":[{"t":"모르겠어… 따뜻한 포를 껴안고 있으면 잠 밖에 안 오는걸…","v":"Idle_01_01","c":0},{"t":"옛날 음악? 엄청 좋아… 그때 사람들은 엄청 행복했을 거야.","v":"Idle_01_02","c":0},{"t":"토끼 귀 귀엽지? 옛날엔 이거 전문적으로 해주는 가게도 있었다던데...","v":"Idle_01_03","c":0},{"t":"지휘관 님도 피곤하면 이거 같이 껴안자. 헤헤. 금방 따뜻해질 거야.","v":"Idle_02_01","c":0},{"t":"바느질? 해줄까? 사령관 님 머리에도 토끼 귀 달아주고 싶어.","v":"Idle_03_01","c":1},{"t":"옛날 영화에서 남자가 여자 헤드폰 씌워주는 거 봤어. 음… 아예 이거 헤드폰으로 바꿔 버릴까?","v":"Idle_04_01","c":0}],"BR_Gremlin":[{"t":"전 기계 공학 전공이지만 사령관 님을 보면 생물학에도 관심이 가네요…","v":"Idle_01_01","c":1},{"t":"제 탑돌이의 제일 야한 부분은 반동으로 접합부에서 살짝 은밀한 부분이 드러날 때예요.","v":"Idle_01_02","c":0},{"t":"오늘은 뭘 만들어 볼까요? 혹시 팔 하나 더 필요하세요?","v":"Idle_01_03","c":0},{"t":"흠… 생물학적 지식으론 알지만… 실제 남성의 신체를 본 적은 없어서요. 혹시… 가능?","v":"Idle_02_01","c":0},{"t":"후후후. 말만 하세요. 신체 일부를 조금 더 보강하는 건 쉬운 일이니. 혹시 필요한 부위라도?","v":"Idle_03_01","c":0},{"t":"아… 저 탑돌이 때문에 살짝 흥분되는데… 흐흐흐… 사령관 님?","v":"Idle_04_01","c":1}],"BR_Impet":[{"t":"사령관 님, 사령관 님에 대한 이 폭발하는 마음을 지금 이 포탄으로 표현해 봐도 될까?","v":"Idle_01_01","c":1},{"t":"심심하면 여기 와서 이야기라도 하자구.","v":"Idle_01_02","c":0},{"t":"밤에 하는 뜨거운 놀이에 대해 어떻게 생각해? 응? 무슨 소리야? 불꽃놀이 이야기지.","v":"Idle_01_03","c":0},{"t":"사령관 님, 가끔씩 사령관 님이랑 이야기할 때, 머리가 폭발해 버릴 것 같을 때가 있어.","v":"Idle_02_01","c":1},{"t":"오늘 밤엔 무슨 뜨거운 놀이를 할까? 설마 불꽃놀이 생각하는 건 아니겠지?","v":"Idle_03_01","c":1},{"t":"조금 더 가까이 와서 이야기해 줘. 그럼 사령관 님도 지금 내 온도를 알겠지?","v":"Idle_04_01","c":1}],"3P_BlackLilith":[{"t":"가장 좋은 호위는 사전 차단이죠. 이 권총은 그러기 위해 있구요.","v":"Idle_01_01","c":0},{"t":"흐흥… 호위를 핑계로 너무 가까이 오신 것 아닌가요? 아, 마음은 이해하지만…","v":"Idle_01_02","c":0},{"t":"여긴 둘뿐이니… 참 좋네요.","v":"Idle_01_03","c":0},{"t":"필요하다면 말만 하세요. 우릴 방해하는 건 모두 부술 테니. 주인님도 그걸 바라지 않나요?","v":"Idle_02_01","c":1},{"t":"주인님? 할 말 없으세요? 언제까지 기다려야 하죠?","v":"Idle_03_01","c":1},{"t":"후후… 조금 더 가까이 오세요. 아예 절 안아 버리면 호위하기가 훨씬 쉬워질 텐데.","v":"Idle_04_01","c":0}],"3P_Alexandra":[{"t":"주인님, 아침 공부는 마치셨나요? 설마… 일부러 벌을 받으려 그러시는 건 아니겠죠?","v":"Idle_01_01","c":1},{"t":"제 마음이 약한 걸 이용하는군요. 주인님처럼 나쁜 학생에겐 벌을 줘야 하는데…","v":"Idle_01_02","c":1},{"t":"후후, 가끔은 학생이 되어 교육을 받고 싶은 적도 있답니다.","v":"Idle_01_03","c":0},{"t":"나쁜 학생이네요. 수업 대신 뭘 하고 싶으신 걸까?","v":"Idle_02_01","c":0},{"t":"주인님이… 선생이 돼서, 절 혼내는 것… 꽤 재미있겠는걸요?","v":"Idle_03_01","c":1},{"t":"네. 네. 벌을 받고 싶으시다면 언제든지 말씀하세요. 조용한 곳이 있을 때요.","v":"Idle_04_01","c":0}],"AGS_Aeda":[{"t":"무슨 명령이 있으십니까?","v":"Idle_01_01","c":0},{"t":"전 인간을 위해 봉사합니다. 과거에도, 그리고 지금도.","v":"Idle_01_02","c":0},{"t":"과거에는 인간과 로봇이 함께 일하던 시절도 있었습니다. 가끔씩은 그립군요.","v":"Idle_01_03","c":0}],"BR_Khan":[{"t":"사령관, 전쟁은 타이밍이다. 상상도 하기 전에 빠른 공격이면 전투는 끝이지.","v":"Idle_01_01","c":1},{"t":"오늘은 전투가 없나?","v":"Idle_01_02","c":0},{"t":"사령관, 누군가 어떤 말을 기다리는 시점이면 이미 늦은 거다. …내 이야긴 아니니 오해는 말도록.","v":"Idle_01_03","c":1},{"t":"사령관, 전쟁만 타이밍이 있는 건 아니다.","v":"Idle_02_01","c":1},{"t":"기다리는 건 익숙하지 않은데… 사령관… 내게 할 말이 없나?","v":"Idle_03_01","c":1},{"t":"전투가 없는 것도 좋군. 사령관과 이렇게 함께 있을 수 있으니.","v":"Idle_04_01","c":1}],"BR_Sylphid":[{"t":"있지… 여긴 좀 잘 나가는 느낌의 애들은 없는 거야?","v":"Idle_01_01","c":0},{"t":"아, 옛날이 좀 그리워. 나 같은 타입이 대세라고 했는데…","v":"Idle_01_02","c":0},{"t":"제복 단추? 아… 그… 내, 내가 좀 개방적인 타입이랄까… 그런 거...","v":"Idle_01_03","c":0},{"t":"사령관, 나랑 다니는 거 자랑스러워해도 돼. 나 완전 잘 나 가거든?","v":"Idle_02_01","c":1},{"t":"음… 사실 난 이 정도로 개방적이고 과감한 성격은 아닌데… 이젠 닫을 필요도 없고.","v":"Idle_03_01","c":0},{"t":"사령관, 혹시 내가 좋아? 뭐, 당연하다고 생각해. 일종의 자연 현상이랄까...","v":"Idle_04_01","c":1}],"BR_SandMan":[{"t":"오늘은 뭘 하고 놀지 고민이에요.","v":"Idle_01_01","c":0},{"t":"가끔씩은 고민이 됩니다. 우리가 전쟁 말고도 의미가 있는 존재인지.","v":"Idle_01_02","c":0},{"t":"내일이 올지 모르니, 오늘을 즐겨야겠죠?","v":"Idle_01_03","c":0},{"t":"가끔씩은 사령관 각하와 환담을 나누고 싶군요.","v":"Idle_02_01","c":1},{"t":"제가 얼마나 더 살지는 몰라도… 지금 이 순간만큼은 즐거운 기분이 드네요.","v":"Idle_03_01","c":0},{"t":"이런 세상에선 사는 의미를 찾기 힘들겠지만 사령관 각하가 제가 사는 의미가 되어 준다면… 좀 더 힘을 낼 수 있을 것 같습니다.","v":"Idle_04_01","c":1}],"3P_Vanilla":[{"t":"요즘은 빗자루보단 이 AK가 청소도구로 더 좋습니다.","v":"Idle_01_01","c":0},{"t":"이 케익 말입니까? 당연히 모조품입니다만? 지능이 낮은 분들은 자주 착각하더군요.","v":"Idle_01_02","c":1},{"t":"심심하시다고요? 죄송합니다. 주인님이 이해할만한 놀이는 생각나지 않는군요.","v":"Idle_01_03","c":1},{"t":"주인님 방을 청소했습니다. 그건... 어디에 숨겨 놓으신 거죠?","v":"Idle_02_01","c":1},{"t":"그렇게 심심하시다면 알겠습니다. 어떤 놀이를… … 건전한 놀이를 찾겠습니다.","v":"Idle_03_01","c":0},{"t":"… 재료를 얻을 수 있을 때, 초코케익을 해드리겠습니다. 아, 특정 날짜에만 가능합니다.","v":"Idle_04_01","c":0}],"AGS_Rampart":[{"t":"심심하십니까? 오메가 산업의 로고송이라도 불러 드릴까요?","v":"Idle_01_01","c":0},{"t":"필요하시다면 시민 편의 기능 작동도 가능은 합니다만…","v":"Idle_01_02","c":0},{"t":"확장형 램파트 구매가 필요하시다면 언제든지 오메가 콜 센터에 문의해 주십시오.","v":"Idle_01_03","c":0}],"BR_Nymph":[{"t":"우습게 들리시겠지만, 좋은 홍차를 구하고 싶을 때가 있어요.","v":"Idle_01_01","c":0},{"t":"바닷속은 참 예뻐요. 가끔씩은 식사를 하다가도 멍하니 보게 돼요.","v":"Idle_01_02","c":0},{"t":"추위를 안 타는 비결요? … 그, 그건 비밀이에요!","v":"Idle_01_03","c":0},{"t":"좋은 차가 있어요. 함께… 하시겠어요?","v":"Idle_02_01","c":0},{"t":"조금 더 날씬해지고 싶지만… 몸에 지방이 충분해야 추운 곳에서 싸울 수 있어서… 절대로 제가 원한 게 아니에요.","v":"Idle_03_01","c":0},{"t":"맛있는 올리브를 얻었어요. … 아침 식사를 차려드리고 싶은데...","v":"Idle_04_01","c":0}],"BR_Pani":[{"t":"에밀리가 재밌지. 나도 좋아해.","v":"Idle_01_01","c":0},{"t":"사령관님… 오늘은 쉬면 안됑?","v":"Idle_01_02","c":1},{"t":"좋아. 결심했어. 오늘은 놀기로! 괜찮지? 사령관님?","v":"Idle_01_03","c":1},{"t":"음… 사령관님이랑 에밀리랑… 혹시 물에 빠지면 누굴 구해야 하지?","v":"Idle_02_01","c":1},{"t":"사령관님, 나랑 재밌는 놀이하자.","v":"Idle_03_01","c":1},{"t":"아, 오늘은 사령관님이랑 잠깐 쉬고 싶어. 저기... 사령관 방에서 잠깐 쉴까?","v":"Idle_04_01","c":1}],"BR_Leona":[{"t":"나에 대해 생각하고 있었어. 난 왜 이렇게 완벽할까?","v":"Idle_01_01","c":1},{"t":"어떤 상이 좋아? 역시 신발로 밟아 주는 쪽?","v":"Idle_01_02","c":0},{"t":"난 사령관이 좀 더 특별한 사람이길 바래. 좀 더 정진해 줘.","v":"Idle_01_03","c":1},{"t":"날 부담스러워할 필요는 없어. 사령관. 나와 함께 있을 사람까지 완벽할 필요는 없으니.","v":"Idle_02_01","c":1},{"t":"… 가끔씩은 사령관도 특별한 사람이라고 생각해. 아주 가끔씩이니까 우쭐 거리지 말아줘.","v":"Idle_03_01","c":1},{"t":"음… 음… 사령관… 내가 잘 하면 상을 줄 거야?","v":"Idle_04_01","c":1}],"PECS_Serpent":[{"t":"하~암!! 오늘은 한가하네.","v":"Idle_01_01","c":0},{"t":"세이프티나 켈베로스는 어른인 척하지만, 아직 애야. 작은 거에 너무 신경을 쓴다니까.","v":"Idle_01_02","c":0},{"t":"혹시 무슨 일 생기면 호출하라고. 사령관. 신호기는 가지고 있지?","v":"Idle_01_03","c":1},{"t":"사령관, 지금 할 일도 없는데 뭐라도 먹을까?","v":"Idle_02_01","c":1},{"t":"꼭 날 호출할 때 비상 상황에만 한다고 생각하지 마. 뭐, 보고 싶으면 호출할 수도 있는 거지. 뭐.","v":"Idle_03_01","c":1},{"t":"사령관, 다른 애들하곤 못하는 어른끼리의 놀이나 해볼까?","v":"Idle_04_01","c":1}],"BR_Scathy":[{"t":"제 몸을 두드리는 거요? 키보드가 내장형이라 어쩔 수 없어요.","v":"Idle_01_01","c":0},{"t":"노출이 심하다니요. 이건 어디까지나 발열을 위한 거예요. 원래 고성능엔 발열이 많이 필요하다구요.","v":"Idle_01_02","c":0},{"t":"건강한 육체에 건전한 정신이 깃드는 법이죠. 마치 저처럼요.","v":"Idle_01_03","c":0},{"t":"키보드를 두드리는 동작이 좀 그런 건... 저도 알고 있어요.","v":"Idle_02_01","c":0},{"t":"제 육체는 제 미모만큼이나 완벽하죠. 후후… 혹시 확인해 보고 싶으세요?","v":"Idle_03_01","c":0},{"t":"노출이 심하다구요? 설마… 사령관님 질투하는 건 아니겠죠? 너무 구속하는 남자는 매력 없어요~!","v":"Idle_04_01","c":1}],"BR_Sleipnir":[{"t":"최고 속도? 내가 누구라고 생각하는 거야? 어쩌면 마음먹으면 마하 100쯤은 나올걸?","v":"Idle_01_01","c":1},{"t":"내 몸매는 완벽한 유선형이지, 가슴? 일부러 줄인 거야.","v":"Idle_01_02","c":0},{"t":"예전엔 내 사인을 받기 위해서 1000미터쯤 줄 서고 했는데...","v":"Idle_01_03","c":0},{"t":"오늘 좀 답답한데 나가서 내 속도를 보여줄까? 응? 마하 100 정도면 괜찮겠지?","v":"Idle_02_01","c":0},{"t":"뭐, 사실 예전 내 팬들은 잊었어. 지금은 더 소중한 게 생겼으니.","v":"Idle_03_01","c":0},{"t":"저… 사령관은 아무래도 풍만한 쪽이 좋아? 아니지? 날씬한 게 더 좋지?","v":"Idle_04_01","c":1}],"BR_Neodym":[{"t":"좋아하는 건 역시 혼자서 노래 부르는 거?","v":"Idle_01_01","c":0},{"t":"어릴 땐 갇혀서 지냈어. 그래서 지금도 조금… 함께 있는 게 낯설어.","v":"Idle_01_02","c":0},{"t":"팬텀이나 레이시나 마찬가지… 우린 특수한 힘을 쓸 수 있게 만들어졌어.","v":"Idle_01_03","c":0},{"t":"그래도 가끔씩은 내가 노래 부르는 걸 누군가 들어줬으면 하는 생각도 있어.","v":"Idle_02_01","c":0},{"t":"자력 때문에 불행했냐고? 음… 예전엔 그렇게 생각한 적도 있었어. 지금은… 아냐 아무것도.","v":"Idle_03_01","c":0},{"t":"끝이 좋으면 좋은 거라고 했어. 이렇게 사령관과 있으니 지금은 좋아.","v":"Idle_04_01","c":1}],"PECS_Express76":[{"t":"미안! 미안! 배송 엄청 밀렸어! 다음에 이야기할래?","v":"Idle_01_01","c":0},{"t":"배송 리스트가… 사령관? 나 오늘 내로 가능할까?","v":"Idle_01_02","c":1},{"t":"어? 날 찾았던 거야? 음… 나 부관 자격 미달이구나. 다음에 혼내줘 알았지?","v":"Idle_01_03","c":0},{"t":"금방 다녀올게, 사령관. 한눈팔면 안 된다? 아, 안돼... 자꾸 그러면 나 안 갈 거야.","v":"Idle_02_01","c":1},{"t":"즐겁냐구? 당연히 즐겁지. 사령관이 날 기다려 주고 있잖아?","v":"Idle_03_01","c":1},{"t":"필요한 곳엔 내가 있을 거야… 약속할게. 사령관…","v":"Idle_04_01","c":1}],"3P_Hachiko":[{"t":"주인님? 혹시, ‘페로’가 어디로 갔는지 알고 계시나요?","v":"Idle_01_01","c":1},{"t":"네? 제가 복슬복슬해서 좋다구요? 어디 가요?","v":"Idle_01_02","c":0},{"t":"네! 주인님, 편하신 대로 다뤄주세요. 우리 뭘 하고 놀까요?","v":"Idle_01_03","c":1},{"t":"친구들도 좋지만, 주인님이랑 같이 있는 게, 제일 좋아요. 헤헤…","v":"Idle_02_01","c":1},{"t":"주인님 손은… 정말 따뜻해서 잠이 올 것 같아요.","v":"Idle_03_01","c":1},{"t":"흐앙~! 머리 쓰다듬어 주시는 거, 너무 좋아요.","v":"Idle_04_01","c":0}],"BR_Djinnia":[{"t":"제가 먹는 이유요? 순수하게 에너지 보충이죠.","v":"Idle_01_01","c":0},{"t":"전 원래 남을 지키기 위해 만들어졌어요.","v":"Idle_01_02","c":0},{"t":"연막탄의 다른 사용법이요? 흠… 식량 창고에 몰래 들어갈 때나 쓸모 있으려나?","v":"Idle_01_03","c":0},{"t":"사령관님, 이거 같이 먹을래요?","v":"Idle_02_01","c":1},{"t":"히히. 사령관님 연막이라도 피울까요? 그럼 우리가 뭐 하는지 아무도 모를 텐데?","v":"Idle_03_01","c":1},{"t":"할 수 있다면 영원히 사령관님을 지키고 싶어요.","v":"Idle_04_01","c":1}],"BR_Blackhound":[{"t":"세상엔 참 신기한 게 많아요. 전부 다 볼 수 있으면 좋겠는데.","v":"Idle_01_01","c":0},{"t":"그냥 친구들 이야길 듣고만 있어도 재밌어요.","v":"Idle_01_02","c":0},{"t":"충성! 사령관님, 여긴 아무 문제없어요.","v":"Idle_01_03","c":1},{"t":"다른 궁금한 것도 많지만… 지금은 사령관님 마음이 궁금해져요.","v":"Idle_02_01","c":1},{"t":"헤헤. 사령관님만 좋으면 전 아무래도 좋아요.","v":"Idle_03_01","c":1},{"t":"사령관님, 모르시죠? 사령관님만 바라보는 사람이 많은걸? 가끔씩은 그것 때문에 우울해지곤 해요.","v":"Idle_04_01","c":1}],"BR_DrM":[{"t":"제일 좋아하는 거? 타이탄이랑… 에이미 언니한테 준 뱀순이?","v":"Idle_01_01","c":0},{"t":"이거? 타이탄 조종해 보고 싶어? 안돼. 우리 타이탄 섬세하단 말야.","v":"Idle_01_02","c":0},{"t":"심심할 땐 비밀 무기를 만들어. 뭐냐고? 당연히 비밀이지.","v":"Idle_01_03","c":0},{"t":"오빠, 못됐어. 흥. 그런 걸 물어보고… 요즘은 좋아하는 게 좀 늘었단 말야…","v":"Idle_02_01","c":1},{"t":"응? 비밀 무기? 음… 오빠한테도 하나 만들어 줄까?","v":"Idle_03_01","c":1},{"t":"으우… 타이탄은 2인용으로 만들 걸 그랬어. 그럼 오빠랑 같이 앉아서 조종할 수 있을 텐데…","v":"Idle_04_01","c":1}],"BR_PXSilky":[{"t":"사령관님? 혹시 제가… 뒤뚱거리면서 걷나요?","v":"Idle_01_01","c":1},{"t":"제가 사령관님 옆에 있다니… 아직 실감이 안 나요.","v":"Idle_01_02","c":1},{"t":"네, 사령관님. 시키실 일이라도 있나요?","v":"Idle_01_03","c":1},{"t":"네? 귀엽다니… 그런 건… 저랑 어울리지 않아요…","v":"Idle_02_01","c":0},{"t":"그런 일을… 시키셔도… 제가... 어떻게 해야 할지…","v":"Idle_03_01","c":0},{"t":"사령관님은 정말 좋으신 분 같아요. 옆에 있기만 해도 마음이 편안해지는걸요?","v":"Idle_04_01","c":1}],"BR_Miho":[{"t":"응? 내 옷에 뭐라도 묻었어? 그럼 떼줘.","v":"Idle_01_01","c":0},{"t":"사령관도 초콜릿 먹고 싶어? 하나 줄까?","v":"Idle_01_02","c":1},{"t":"저기, 사령관...? 요즘… 할 일이 없는 거야?","v":"Idle_01_03","c":1},{"t":"에잇! 그만 좀... 쳐다봐. 부끄럽단... 말이야…","v":"Idle_02_01","c":0},{"t":"아니, 바쁜 일 없어. 지금은 사령관이랑 둘이서 이야기하고 싶어… 오늘... 어땠어?","v":"Idle_03_01","c":1},{"t":"초콜릿? 주머니에 있으니까 꺼내 먹… 자꾸 거기에 손 넣지 마. 이 바보야…","v":"Idle_04_01","c":0}],"BR_Calista":[{"t":"여기선 너무 딱딱하게 굴 필요 없으니까, 재밌는 이야기라도 할래?","v":"Idle_01_01","c":0},{"t":"뭣하면, 내가 지원 가줄 수 있어. 명령만 해~.","v":"Idle_01_02","c":0},{"t":"응. 역시 아군이 다치지 않는 쪽이 최선이지. 난, 사령관의 그런 점이 좋아.","v":"Idle_01_03","c":1},{"t":"내가 튼튼하긴 하지만, 그렇게 막 다루면... 고장 날지도 몰라…","v":"Idle_02_01","c":0},{"t":"며… 명령을 내리는 사람에게 반하는 건… 흔한 일이라구...","v":"Idle_03_01","c":0},{"t":"오늘은, 우리 뭘 하고 지낼까? 헤헤...","v":"Idle_04_01","c":0}],"BR_Wraithy":[{"t":"조금만 쉬다가... 떠나겠어요… 폐 끼치지 않을게요.","v":"Idle_01_01","c":0},{"t":"사령관님의 아픔이, 느껴져요. 오늘… 무슨 일이 있었나요?","v":"Idle_01_02","c":1},{"t":"당신은 상냥하시군요… 누구에게나 따뜻하신 분…","v":"Idle_01_03","c":1},{"t":"제가… 여기 머물러도 될까요? 고마워요… 상냥하신 분…","v":"Idle_02_01","c":0},{"t":"미안해요… 당신이... 제게만 상냥한 사람이 되어주면 좋겠다고 생각했어요…","v":"Idle_03_01","c":1},{"t":"괜찮을 거예요… 모두 괜찮아질 거예요… 제가 옆에 있어 드릴게요.","v":"Idle_04_01","c":0}],"3P_Aqua":[{"t":"주인님? 난 정원에 다녀올게! 케이크는 식탁에 있는데, 내 건 남겨둬야 해.","v":"Idle_01_01","c":1},{"t":"난 정의의 요정이야. 해충을 박멸하고, 세계를 구할 거야. 주인님도 같이 할래?","v":"Idle_01_02","c":1},{"t":"주인님? 내가 언니들 보다 훨씬 낫지? 응?","v":"Idle_01_03","c":1},{"t":"정원 관리는 잘 하고 있으니까 이제... 주인님이랑 잠깐 티타임이야.","v":"Idle_02_01","c":1},{"t":"난 언니들한테는 없는 무기가 있지! 그건 바로...!","v":"Idle_03_01","c":0},{"t":"나도 언젠가는, 주인님처럼 영웅이 될 수 있겠지? 너무 오래 걸리면 안 되는데...","v":"Idle_04_01","c":1}],"BR_WarWolf":[{"t":"사령관은 무슨 생각 하고 있어? 난, 어제 날려먹은 것들 생각하고 있었지.","v":"Idle_01_01","c":1},{"t":"좋아하는 거? 몰래 한잔하는 거지~! 같이 갈래 사령관?","v":"Idle_01_02","c":1},{"t":"사령관이 멍한 얼굴을 하고 있어서, 나까지 좀 늘어지는 기분이야.","v":"Idle_01_03","c":1},{"t":"어머~? 지금 응석 부리는 거야? 귀여워라... 이 누나랑 재밌는 거 하러 갈래?","v":"Idle_02_01","c":0},{"t":"그거 알아? 사령관은 하품하는 모습이 제일 귀여워. 그러니까... 다른 애들한테는 보여주지 마.","v":"Idle_03_01","c":1},{"t":"어쩜... 그때 한잔하는 게 아니었는데… 사령관이랑 이렇게 될 줄... 누가 알았겠어?","v":"Idle_04_01","c":1}],"BR_Daika":[{"t":"네, 사령관님. 오늘의 날씨 말씀이신가요? 음... 어떨까요?","v":"Idle_01_01","c":1},{"t":"차를 한잔 드릴까요? 따뜻한 것과, 차가운 것. 어떤 걸 원하시나요?","v":"Idle_01_02","c":0},{"t":"기밀문서 말씀이시군요. 음... 접근 권한이 모자라세요… 후훗... 힘내 주세요 사령관님.","v":"Idle_01_03","c":1},{"t":"날씨가 흐려도 옅은 비 정도는 제가 가려드릴 수 있으니, 저와 함께 가시겠어요?","v":"Idle_02_01","c":0},{"t":"접근 권한 확인. 둠 브링어 팀. ‘B’사이즈, 열람… 으음~ 안돼요 사령관님. 다른 곳에 힘써주세요~.","v":"Idle_03_01","c":1},{"t":"어떤 차를 좋아하냐면… 사령관님을 바라보며 마시는 차? 후훗! 정말 부끄럽네요~.","v":"Idle_04_01","c":1}],"BR_QuickCamel":[{"t":"응! 나 여기 있어. 무슨 일이야? 그냥… 불러 봤다고?","v":"Idle_01_01","c":0},{"t":"흐음~! 사령관. 나랑 뭐라도 마시러 갈까? 괜찮아, 내가 살 테니까.","v":"Idle_01_02","c":1},{"t":"여긴 정말 느긋하구나? 응~! 마음에 들어.","v":"Idle_01_03","c":0},{"t":"별일 없어도, 계속 불러줘. 사령관이 관심 있다는 증거니까. 난 기분 좋아.","v":"Idle_02_01","c":1},{"t":"헤헷! 사령관이 여기 있으니까, 나가기 싫은 거 있지? 나 사실 엄청 게으르거든?","v":"Idle_03_01","c":1},{"t":"너무 가까이 붙진 말아줘. 시… 싫다는 건 아니고, 그, 그냥… 헤헤…","v":"Idle_04_01","c":0}],"BR_Bulgasari":[{"t":"뭐야, 사령관? 찔리는 거라도 있어?","v":"Idle_01_01","c":1},{"t":"응. 출격 때 빼고는 한가한 편이야... 어… 근데, 그거 데이트 신청이지?","v":"Idle_01_02","c":0},{"t":"머리핀은 많은데, 아까워서 하나만 끼고 다녀. 가난한 게 아니라, 절약이라고.","v":"Idle_01_03","c":0},{"t":"어… 신경 쓰지 마. 그냥 쳐다보고 있는 것뿐이야… 하던 일 계속해줘 사령관.","v":"Idle_02_01","c":1},{"t":"아~! 사령관이랑 팔짱 끼고 쇼핑 다니고 싶다. 어? 쇼핑은 별로라니... 대체 왜?","v":"Idle_03_01","c":1},{"t":"음… 그러고 보면 사령관도 제법 잘생겼단 말이지. ...그렇게 우쭐거릴 정도는 아니거든?","v":"Idle_04_01","c":1}],"PECS_Stinger":[{"t":"스팅어 모델은 돌파 작전에 사용됩니다.","v":"Idle_01_01","c":0},{"t":"주된 파괴 대상은 소행성입니다.","v":"Idle_01_02","c":0},{"t":"파괴. 돌파. 파괴. 돌파.","v":"Idle_01_03","c":0}],"AGS_Seljuq":[{"t":"사령관님? 거긴 위험합니다. 발밑을 조심하십시오.","v":"Idle_01_01","c":1},{"t":"저는 감정 모듈이 없습니다. 유사한 시스템이 탑재되어 있을 뿐입니다.","v":"Idle_01_02","c":0},{"t":"저는 수시로 정비가 필요합니다. 지원 감사합니다.","v":"Idle_01_03","c":0}],"AGS_Gigantes":[{"t":"중갑 돌파용 기간테스.","v":"Idle_01_01","c":0},{"t":"파괴, 돌파, 반복.","v":"Idle_01_02","c":0},{"t":"기간테스. 명령 대기중.","v":"Idle_01_03","c":0}],"AGS_Shade":[{"t":"함 내에서는 은신이 금지되어 있습니다.","v":"Idle_01_01","c":0},{"t":"암살에는 여러 가지 방법이 있습니다. 사령관께서는 어떤 방법을 선호하십니까?","v":"Idle_01_02","c":1},{"t":"과거의 암살 사례에 대해서는 데이터베이스를 요청해 주십시오.","v":"Idle_01_03","c":0}],"DS_MoMo":[{"t":"언젠가, 매지컬 모모 스티커가 유행했던 거 아세요? 어린이 친구들에게... 인기가 정말 많았죠.","v":"Idle_01_01","c":0},{"t":"네~! 모모는 사령관님 곁에 있답니다? 어떤 것을 도와드릴까요?","v":"Idle_01_02","c":1},{"t":"나쁜 악당과 맞서는 건, 마법 소녀의 숙명이에요.","v":"Idle_01_03","c":0},{"t":"저… 사령관님? 마침 제게 매지컬 모모 정품 스티커가 있는데… 괜찮으시다면, 하나 드릴까요?","v":"Idle_02_01","c":1},{"t":"악당을 물리치는 것도 중요하지만... 지금은... 사령관님과 같이 있고 싶은걸요?","v":"Idle_03_01","c":1},{"t":"모모는 항상 사령관님 곁에 있겠어요. 그렇지만, 그걸 잊어버리면 안 되니까 마법을 걸어드릴게요. 절대 잊으면 안 돼요?","v":"Idle_04_01","c":1}],"DS_Atalanta":[{"t":"무료하군요. 사냥도, 연회도 없는 이런 곳에서 어떻게 지낼 수 있지요?","v":"Idle_01_01","c":0},{"t":"진짜 남자라면, 자기 여자를 지킬 수 있어야죠.","v":"Idle_01_02","c":0},{"t":"네, 제게 뭔가 시키실 일이라도 있나요?","v":"Idle_01_03","c":0},{"t":"후후... 그대 곁에 있으니, 이곳 생활도 그리 나쁘지만은 않군요.","v":"Idle_02_01","c":0},{"t":"원하는 건, 말씀만 하세요. 제가 뭐든 들어 드릴 테니까요.","v":"Idle_03_01","c":0},{"t":"그래요. 어쩌면 전... 그대와 함께하는… 이런 삶을 바래왔을지도…","v":"Idle_04_01","c":0}],"BR_Phoenix":[{"t":"내가 무겁다는 소리는 어디서 들은 거야? 누가 그러는 건데?","v":"Idle_01_01","c":0},{"t":"우리 사령관도 정말 끈질기네… 내가 뭘 해주면 좋을까?","v":"Idle_01_02","c":1},{"t":"위에서 내려다보는 건, 내 특권이지.","v":"Idle_01_03","c":0},{"t":"사령관, 오해를 할까 봐 말하는데, 난 절대로 무겁지 않아. 그냥 포탄을 많이 들고 다닐 뿐이야.","v":"Idle_02_01","c":1},{"t":"사령관, 자신감을 가져. 사령관은 내가 내려다보지 않는 유일한 사람이니.","v":"Idle_03_01","c":1},{"t":"자! 내 추리를 말할게. 사령관의 심박수나 홍조 등을 생각해 보면… 이 변태! 정말 그걸 하고 싶은 거야?","v":"Idle_04_01","c":1}],"BR_Undine":[{"t":"나? 인기 만점이었지. 비행쇼라도 하면, 내 부스가 최고로 북적거렸다고…","v":"Idle_01_01","c":0},{"t":"흥. 자꾸 말 걸지 말았으면 좋겠어. 나 조용한 걸 좋아하는 편이니까.","v":"Idle_01_02","c":0},{"t":"사령관, 오늘 얼굴을 보니… 여자에 관련된 고민이 있구나? 응? 아니라고?","v":"Idle_01_03","c":1},{"t":"솔직히 말하면… 인기에 비해선 판매량은 좀 저조하긴 했어. 뭐, 그리폰같은 염가형이 잘 팔리긴 했으니까…","v":"Idle_02_01","c":0},{"t":"사령관, 고민이 많은 얼굴이네? 혹시… 걱정 마. 사령관, 나 그렇게 눈이 높진 않으니까!","v":"Idle_03_01","c":1},{"t":"사령관, 뭐 바쁜 일이라도 있어? 왜 보기만 하는 거야? 혹시… 나한테 화난 거라도 있어?","v":"Idle_04_01","c":1}],"PECS_Carolina":[{"t":"저기... 사령관? 나 역시… 다이어트해야 할까? 괜찮아, 솔직하게 말해줘…","v":"Idle_01_01","c":1},{"t":"응! 치어리더는 절대 같은 팀이 질 거라고 생각 안 해! 사령관도 그렇게 생각하지?","v":"Idle_01_02","c":1},{"t":"응? 이렇게? 이렇게? 좀 더 빠르게 할까?","v":"Idle_01_03","c":0},{"t":"오우... 다이어트하지 말란 게, 그런 이유였어? 응~! 알았어 사령관.","v":"Idle_02_01","c":1},{"t":"그… 그런... 리퀘스트는 무조건 패스지만… 그렇게… 보고 싶어?","v":"Idle_03_01","c":0},{"t":"사령관만 있으면, 어딜 가든 잘 할 자신 있어. 사령관도 나 믿지?","v":"Idle_04_01","c":1}],"ST_Lancer":[{"t":"전 쉴 틈이 없어요. 증명해야 한다구요.","v":"Idle_01_01","c":0},{"t":"비전투 유닛을 보는 시각을 바꿔야 해요!","v":"Idle_01_02","c":0},{"t":"오늘도 훈련이에요! 라비아타 님에게 보답하려면.","v":"Idle_01_03","c":0},{"t":"가끔씩은… 사령관과 시간을 보내는 것도… 좋을 지도?","v":"Idle_02_01","c":1},{"t":"사령관 님, 훈련을 봐주시지 않겠어요? 그럼 저... 더 힘낼 수 있으니까!","v":"Idle_03_01","c":1},{"t":"아무래도 상관없어요. 지금은 사령관 님이 절 바라봐 주기만 하면… 힘낼 수 있어요.","v":"Idle_04_01","c":1}],"PECS_Audrey":[{"t":"여기 자매들은 모델이 되기엔 좀… 너무 커요. 나이트 앤젤 양 빼곤… 인재가 부족하군요?","v":"Idle_01_01","c":0},{"t":"조금… 영감이 부족해요. 자극이 필요한데…","v":"Idle_01_02","c":0},{"t":"사령관은 빼쑌을 좀 더 가다듬을 필요가 있겠군요?","v":"Idle_01_03","c":1},{"t":"어때요? 사령관, 제 런웨이에 서고 싶은 생각 있어요?","v":"Idle_02_01","c":1},{"t":"뭐… 패션의 완성은 얼굴이란 점에서… 흐음… 사령관은 거의 완성된 것 같기도 하네요.","v":"Idle_03_01","c":1},{"t":"으음… 요즘은 자극이 너무 강해요. 왜 모르겠다는 얼굴이죠? 다 사령관 때문인데…","v":"Idle_04_01","c":1}],"BR_Gnome":[{"t":"걱정 마세요. 제가 지켜 드릴게요.","v":"Idle_01_01","c":0},{"t":"이건 발포 콘크리트 탄이에요. 일종의 팽창 시멘트에 형상 기억 합금을 넣은 거죠.","v":"Idle_01_02","c":0},{"t":"도망갈 생각은 없어요. 제가 도망가면, 모두가 위험해질 테니까요.","v":"Idle_01_03","c":0},{"t":"사령관 님을 지키는 건… 꼭 가족이라서가 아니에요. 그냥… 지키고 싶은 거예요.","v":"Idle_02_01","c":1},{"t":"사령관 님과 있으면 언제나 힘이 나요.","v":"Idle_03_01","c":1},{"t":"… 콘크리트 벽 뒤에선 아무도 못 봐요… 살짝 터뜨릴까요?","v":"Idle_04_01","c":0}],"3P_Sowan":[{"t":"주특기 요리는 채소 케이크입니다. 맛이 궁금하신가요?","v":"Idle_01_01","c":0},{"t":"소첩의 목표... 말씀이시옵니까? 후후. 비밀이옵니다.","v":"Idle_01_02","c":0},{"t":"빠른 칼질과, 튼튼한 하체는 요리의 기본이옵니다.","v":"Idle_01_03","c":0},{"t":"숨김 맛으로… 제가 무엇을 넣었을 것 같습니까? 후후후…","v":"Idle_02_01","c":0},{"t":"소첩의 솜씨가 전투와 쾌락 양쪽에 도움을 드릴 수 있어 다행이옵니다.","v":"Idle_03_01","c":0},{"t":"어떠시옵니까? 후후. 이젠 저 없이는 안되는 몸이 되지 않으셨는지요? … 이제 주인은 제 것이옵니다.","v":"Idle_04_01","c":0}],"AGS_SpartanA":[{"t":"스파르탄 어설트. 섬멸 작전 특화.","v":"Idle_01_01","c":0},{"t":"전투 데이터 기록 중… 더미 데이터 소거 완료.","v":"Idle_01_02","c":0},{"t":"신속한 명령 요청.","v":"Idle_01_03","c":0}],"AGS_SpartanB":[{"t":"스파르탄 부머. 대기 중.","v":"Idle_01_01","c":0},{"t":"명령 수행 최우선.","v":"Idle_01_02","c":0},{"t":"안전거리 확보 요청.","v":"Idle_01_03","c":0}],"AGS_SpartanC":[{"t":"스파르탄은 최강이자 최고 효율의 보병 로봇입니다.","v":"Idle_01_01","c":0},{"t":"안타깝게도 멸망 전쟁 땐 저희가 존재하지 않았습니다.","v":"Idle_01_02","c":0},{"t":"스파르탄은 명령을 수행합니다. 이것은 스파르탄입니다.","v":"Idle_01_03","c":0}],"PECS_ElvenForestmaker":[{"t":"저 인기 엄청 많았어요. 팬클럽도 있었다구요~.","v":"Idle_01_01","c":0},{"t":"아~! 놀러 가고 싶다… 그냥... 그냥 그렇다구요.","v":"Idle_01_02","c":0},{"t":"으~! 정말… 매일 웃는 것도 완전 스트레스 쌓이거든요?","v":"Idle_01_03","c":0},{"t":"저… 그렇게 성격 좋은 애는 아닌걸요...? 그래도... 괜찮아요?","v":"Idle_02_01","c":0},{"t":"전 그래도, 진짜 좋은 사람 만난 것 같아서 다행이에요.","v":"Idle_03_01","c":0},{"t":"안되겠다. 우리 사령관님이랑 놀러 가야지~. 얼른 휴가 내세요. 빨리요~.","v":"Idle_04_01","c":1}],"PECS_BS":[{"t":"쬐끔 힘들어도, 나름 보람 있는 일이랍니다?","v":"Idle_01_01","c":0},{"t":"역시, 퇴근 후에 마시는 맥주가 최고죠.","v":"Idle_01_02","c":0},{"t":"헤헷. 제가 안 가면 누가 가겠어요?","v":"Idle_01_03","c":0},{"t":"하암… 어제도... 일찍 자는데 실패했습니다~.","v":"Idle_02_01","c":0},{"t":"오늘만... 사령관님이랑 쉬면 안될까요? 딱~. 하루 만요~.","v":"Idle_03_01","c":1},{"t":"저… 사령관님? 맥주 가져왔는데. 생각 있으세요?","v":"Idle_04_01","c":1}],"DS_Charlotte":[{"t":"좋아하는 건… 아! 익힌 감자에 소금이면… 음~.","v":"Idle_01_01","c":0},{"t":"모두 앞에서 다시 공연할 수만 있다면… 전 뭐든지 할 수 있어요!","v":"Idle_01_02","c":0},{"t":"마리 양은, 정말 꽉 막힌 아가씨에요. ‘멋’을 이해하지 못하다니… 뭐, 조금 안쓰럽기도 하네요.","v":"Idle_01_03","c":0},{"t":"으, 음식에는 귀천이 없다고 생각해요.","v":"Idle_02_01","c":0},{"t":"읏! 어떻게 모자의 깃털을 포기할 수 있지요? 마리 양은 정말 ‘멋’을 모른다니까요?","v":"Idle_03_01","c":0},{"t":"폐하께만 보여드리고 싶은 게 있어요… 부디... 솔직한 감상을 들려주시겠어요?","v":"Idle_04_01","c":0}],"BR_Spriggan":[{"t":"내 패션 센스를 보여주고 싶지만. 군복으로는 이게 한계야. 어디, 괜찮은 아이디어 없어?","v":"Idle_01_01","c":0},{"t":"오늘은 누구 얘길 해줄까? 칼리스타? 이오? 아냐, 그냥 소문이 아니고. 내가 직접 확인한 거라니까?","v":"Idle_01_02","c":0},{"t":"내 이야기? 그건... 갑자기 왜? 음… 아직, 안되는데…","v":"Idle_01_03","c":0},{"t":"정말… 군복으로도 괜찮아? 아니, 그게 취향이라면… 어쩔 수 없지만…","v":"Idle_02_01","c":0},{"t":"내 비밀 이야기가 듣고 싶은 거지? 알았어~. 나중에 내 방으로 와. 패스워드 알려줄까?","v":"Idle_03_01","c":0},{"t":"우리 둘이 무슨 일 있는 거, 애들이 다 알고 있던데… 응! 그것도 소문 다 났어… 이제… 어떻게 할 거야…","v":"Idle_04_01","c":0}],"BR_Sirene":[{"t":"장난감 뱀이라니… 하아… 네리 씨는 이게 정말 재밌다고 생각하는 걸까요?","v":"Idle_01_01","c":1},{"t":"사령관님, 어떻게 하면 대원들과 더 친해질 수 있을까요?","v":"Idle_01_02","c":1},{"t":"전, 호라이즌 대원들을 지휘할 의무가 있어요.","v":"Idle_01_03","c":0},{"t":"후훗! 네리 씨는 늘 즐거워 보여요. 잘못을 지적할 때도 늘 똑같은 표정이죠… … 대체... 왜 그럴까요?","v":"Idle_02_01","c":0},{"t":"그래도 한 번쯤은… 사령관님과 놀러 나가고 싶어요. 그래도… 될까요?","v":"Idle_03_01","c":1},{"t":"그렇지만, 전 사령관님과 더 친해지고 싶은걸요? 사령관님은, 어떻게 생각하세요?","v":"Idle_04_01","c":1}],"DS_Azazel":[{"t":"제가 있는 이상, 누구도 다치지 않습니다.","v":"Idle_01_01","c":0},{"t":"너무 여성들을 가까이 두지 마세요. 음란함에 빠지는 것은 죄를 짓는 것입니다.","v":"Idle_01_02","c":0},{"t":"제가 올바른 길과 정결한 삶을 알려 드리죠. 마음을 바르게 하고 들어 주세요.","v":"Idle_01_03","c":0},{"t":"전 모든 생명에게 공정해야 하지만… 인간 남성, 당신은 조금 더 특별하게 대해도 되겠죠?","v":"Idle_02_01","c":1},{"t":"바, 반… 인간 남성! 오늘의 계획은 어떻게 되죠? 올바른 세상을 만들 계획을 함께 세워보죠.","v":"Idle_03_01","c":0},{"t":"반려. 걱정 마세요. 첩들의 사소한 일은 제가 관리할 테니. 반려께선 중요한 일만 신경 써 주세요.","v":"Idle_04_01","c":0}],"PECS_Triaina":[{"t":"사령관! 내가 좋은 정보를 알아 왔는데 말야. 어때? 들어볼래?","v":"Idle_01_01","c":1},{"t":"난 언제나 솔직해. 내 말만 들으면 사령관도 대박을 챙길 수 있다고.","v":"Idle_01_02","c":1},{"t":"바다에서 길을 찾는 방법? 당연히 물고기들에게 길을 묻는 거지. 예를 들어 바다거북이나…","v":"Idle_01_03","c":0},{"t":"흠… 사령관에게만 알려 주는 거야. 이 근처에 금괴를 실은 배가 가라앉아 있대. 히~ 사령관은 어떻게 생각해?","v":"Idle_02_01","c":1},{"t":"음… 솔직히 말하면… 어군 탐지기로 물고길 쫓아가는 거긴 한데… 그… 그것도 일종의 대화라고! 커뮤니케이션 몰라?","v":"Idle_03_01","c":0},{"t":"몰라. 이젠 대박보다 사령관하고 있는 게 더 좋아. 사령관도 그렇지? 응? 응?","v":"Idle_04_01","c":1}],"AGS_Roc":[{"t":"생명에는 가치가 없습니다. 결국은 유전자의 명령을 따르는 생존 기계일 뿐이죠.","v":"Idle_01_01","c":0},{"t":"주인의 명령에 따라 전 더 완전해질 수 있습니다.","v":"Idle_01_02","c":0},{"t":"생명이 사라지는 걸 보면 언제나 즐겁군요. 그게 기계 생명이라도 말이죠.","v":"Idle_01_03","c":0}],"3P_Rhea":[{"t":"가사를 좀 더 배웠으면 좋았을 텐데…","v":"Idle_01_01","c":0},{"t":"아쿠아는 정말 귀여워요. 그 아이가 언니들이랑 조금만 더 잘 어울리면 좋을 텐데…","v":"Idle_01_02","c":0},{"t":"혹시 비 오는 날… 좋아하세요? 필요하시면… 언제든지 말씀만 하세요.","v":"Idle_01_03","c":0},{"t":"전… 요리보단 더 중요한 걸 할 수 있으니까요. 그리고… 연습할 테니까… 조금만 기다려 주세요.","v":"Idle_02_01","c":0},{"t":"봄비가 내릴 땐… 주인님과 함께 거닐고 싶어요. … 둘이서만…","v":"Idle_03_01","c":1},{"t":"후후. 주인님도 절 누나처럼 여기셔도 돼요. 아, 누나처럼이에요. 처럼. 정말 누나가 되어 버리면 곤란하니까.","v":"Idle_04_01","c":1}],"PECS_Ignis":[{"t":"태우는 일이요? 이것저것… 해가 되거나, 필요 없는 걸 태우곤 했습니다.","v":"Idle_01_01","c":0},{"t":"죄송합니다… 작업 후에 와서… 땀이 좀 많이 났습니다.","v":"Idle_01_02","c":0},{"t":"엘븐은 절 질색합니다… 제가 나무를 태우거나 하진 않는데 말입니다.","v":"Idle_01_03","c":0},{"t":"뭐, 뭘 태우자구요? 그건 갑자기 무슨 말입니까?","v":"Idle_02_01","c":0},{"t":"저… 기회가 된다면 엘븐과... 화해할 기회를 주시지 않겠습니까?","v":"Idle_03_01","c":0},{"t":"지금 땀이 나는 게… 작업 때문인지… 사령관 님 때문인지 구분할 수가 없습니다.","v":"Idle_04_01","c":1}],"PECS_Empress":[{"t":"어때? 조금은 환경 보호의 중요성에 대해 알겠어?","v":"Idle_01_01","c":0},{"t":"철충들은 다른 동물들에 대해선 관심이 없는 것 같아. 생태에 대해 좀 더 조사를 해 봐야겠어.","v":"Idle_01_02","c":0},{"t":"나, 남극이나 북극에서 활동하다 보면! 이 정도 지방은! 당연한 거야! 알겠어?!","v":"Idle_01_03","c":0},{"t":"사령관, 인간님이 늘어나면 환경 보존에 더 신경 써야 할 거야. 그땐… 같이해 줄 거지?","v":"Idle_02_01","c":1},{"t":"진짜! 살찐 거 아니라니까! 지금 확인시켜줘?","v":"Idle_03_01","c":0},{"t":"인간님들이 멸망한 건 슬프지만 사령관이 살아남아서 기뻐. 사령관, 항상 조심해야 해!","v":"Idle_04_01","c":1}],"3P_Alice":[{"t":"이런 날은 우울하군요. 무료하고. 콘스탄챠 언니나 좋아할 날씨예요.","v":"Idle_01_01","c":0},{"t":"미사일을 쏠 때 부끄럽지 않냐고요? 오히려 해방감에 기분이 좋아지는걸요?","v":"Idle_01_02","c":0},{"t":"며칠 전, 몇몇 바이오로이드들이 제게 노출증에 대해 묻더군요. 정말… 노출증을 본 적이 없는 걸까요? 아니면 양심이?","v":"Idle_01_03","c":0},{"t":"후훗… 심심한데… 놀아줄까요?","v":"Idle_02_01","c":0},{"t":"자꾸 다른 바이오로이드들에게 눈이 돌아가시는데… 또 그러시면 혼내 드리겠어요. 후후. 궁금하신가요?","v":"Idle_03_01","c":0},{"t":"정말 하찮은 걱정을 하시는군요. 다른 이들은 절 보는 게 끝이에요. 절벽 위의 꽃처럼.","v":"Idle_04_01","c":0}],"BR_Lindwurm":[{"t":"싸움만 하기엔, 린티가 아깝다고 생각해요.","v":"Idle_01_01","c":0},{"t":"흐응- 린티는 이렇게 귀여운데, 어째서 군인으로 태어난 걸까요?","v":"Idle_01_02","c":0},{"t":"‘린트블룸’보다는, ‘린티’ 라고 불러주시겠어요? 그쪽이 훨씬 귀여우니까요~!","v":"Idle_01_03","c":0},{"t":"네~! 최고로 귀여운 린티를 찾으셨나요?","v":"Idle_02_01","c":0},{"t":"후훗~! 부끄러워하지 말고, 절 따라 해보세요. 자아- 린.티. 다시 한번~. 린.티.","v":"Idle_03_01","c":0},{"t":"그래서, 린티는 세상에서 제일 귀여운 군인이 되기로 결심했죠. 그러니까, 사령관님도 린티를 도와주셔야 해요. 아셨죠?","v":"Idle_04_01","c":1}],"AGS_Fortress":[{"t":"전 아군의 방벽이 되기 위해 태어났습니다.","v":"Idle_01_01","c":0},{"t":"걱정 마십시오. 제 방벽 뒤에선 안전합니다.","v":"Idle_01_02","c":0},{"t":"몇몇 여성형 바이오로이드가 위험한 행동을 할 때에는 제 뒤로 피해 주시기 바랍니다.","v":"Idle_01_03","c":0}],"DS_Baekto":[{"t":"제 소명은 뽀끄루 대마왕의 지구 정복을 막는 것… 그 외엔 관심이 없어요.","v":"Idle_01_01","c":0},{"t":"문 라이트 매지컬 파워는 우정과 용기에서 나옵니다.","v":"Idle_01_02","c":0},{"t":"흥, 모모는 마의 위험을 제대로 모르고 있어요. 제가 그녀를 일깨우겠어요.","v":"Idle_01_03","c":0},{"t":"으음… 선대의 백토에게도… 가끔씩 번뇌는 있었겠죠?","v":"Idle_02_01","c":0},{"t":"가끔씩은… 마족보다… 철충이 더 위협적이지 않나 생각할 때가 있어요.","v":"Idle_03_01","c":0},{"t":"어쩌면, 사랑으로도 문 라이트 매지컬 파워를… 채울 수 있을 지도… 아, 잊어 주세요.","v":"Idle_04_01","c":0}],"DS_Faucre":[{"t":"공연할 때는 좋았어요. 헤헤. 모모랑 백토랑 다른 친구들 보는 것도 좋았는데…","v":"Idle_01_01","c":0},{"t":"정말… 대마왕 아니에요! 사장님까지 왜 그러시는 거예요?","v":"Idle_01_02","c":0},{"t":"싸움보단 음악을 듣는 게 좋아요.","v":"Idle_01_03","c":0},{"t":"으으.... 백토가 또 절 괴롭히면 막아주실 거죠? 그렇죠?","v":"Idle_02_01","c":0},{"t":"저.... 나중에 싸움이 없어지면…. 절 가수로 고용해 보는 건 어때요? 그쪽은 자신 있는데....","v":"Idle_03_01","c":0},{"t":"히잉… 사장님이 원하시면… “후후… 나의 총애를 바라느냐?”","v":"Idle_04_01","c":0}],"BR_Bheur":[{"t":"정말! LRL 에겐 정리 정돈하면서 놀라고 했는데…","v":"Idle_01_01","c":0},{"t":"사령관? 이거, 안 챙기면 무슨 일이 벌어질지 몰라요. 꼭 챙기셔야 해요. 꼭이에요!","v":"Idle_01_02","c":1},{"t":"사령관? 제가 보기엔 배치 편성을 이렇게 해야 빈틈이 없을 것 같아요.","v":"Idle_01_03","c":1},{"t":"사령관?! LRL이 함교에 버린 참치캔들 보셨어요? 제가 한소리 해도 되죠?!","v":"Idle_02_01","c":1},{"t":"사령관...? 지금 속으로...제가 귀찮다고 생각하셨죠? 그렇죠? 그러면 안 돼요. 제가 혼내줄 거예요!","v":"Idle_03_01","c":1},{"t":"이럴 줄 알았어요~. 플레이트 안 끼우셨죠? 얼른 이리 와봐요. 아, 얼른요~.","v":"Idle_04_01","c":0}],"PECS_DarkElf":[{"t":"저기? 여기만 계속 쳐다보는 거… 은근 신경 쓰이거든?","v":"Idle_01_01","c":0},{"t":"그… ‘당신’이라는 게... 그런 뜻도 있었다네? ...하하…","v":"Idle_01_02","c":1},{"t":"뭐? 정말 캠프파이어 같은 걸 하고 싶은 건 아니지? … 하, 한 번도 해본 적 없어?","v":"Idle_01_03","c":0},{"t":"이거? 교복이 아니라, 공식 제복인데? 뭔가 문제 될 거라도 있어?","v":"Idle_02_01","c":0},{"t":"캠프파이어? 아, 알았어. 해주면 되잖아… 대신, 장작은 당신이 구하는 거다?","v":"Idle_03_01","c":1},{"t":"내가 ‘당신’이라고 부르는 건, 그냥 익숙해서 그러는 거야. 다른 뜻은 없다고.","v":"Idle_04_01","c":1}],"BR_Alvis":[{"t":"히히. 사령관님은 뭐든 잘 먹는구나? 이거 하나 더 먹을래? 걱정 마 초코바는 여기 잔뜩 있으니까.","v":"Idle_01_01","c":1},{"t":"무서울 땐 거기서 웅크리고 있어. 그럼 알비스가 지켜 주러 갈게!","v":"Idle_01_02","c":0},{"t":"이건, 베라 언니 꺼! 이건… 발키리 언니 꺼! 님프 언니는 살쪄서 간식 안 먹는대!","v":"Idle_01_03","c":0},{"t":"그거 알아? 초코바 하나엔 자그마치 초코바 하나 분량의 칼로리가 들어있대! 그래서 옛날에 군인들은… 응? 무슨 소린지 모르겠다구?","v":"Idle_02_01","c":0},{"t":"초코바는 님프 언니가 방금 세 개나 가져가서 이제 없어. 알비스가 나중에 구해줄 테니까, 얌전히 기다리고 있어야 돼.","v":"Idle_03_01","c":0},{"t":"알비스가 위험하면 사령관님이 도와주러 와야 해. 약속했다? 꼭이다?","v":"Idle_04_01","c":1}],"BR_Raven":[{"t":"사령관이 우리 애들을 잘 지켜줘서, 내가... 얼마나… 편한지 몰라! 정말 너-무 좋아! 앞으로도 잘 부탁해 사령관~!","v":"Idle_01_01","c":1},{"t":"사령관? 여깄으면 조금 갑갑하지 않아? 나랑 놀러나갈 생각 없어? 응?","v":"Idle_01_02","c":1},{"t":"제멋대로인 누나랑 지내는 기분은 어때? 후훗, 나중에 보답해 줄 테니까 조금만 힘내 사령관.","v":"Idle_01_03","c":1},{"t":"우리 동생들한테 손댈 바에는, 차라리 나를... 아, 아냐. 아무것도 아냐…","v":"Idle_02_01","c":0},{"t":"흥! 누나한테 철없다는 소리 하는 거 아니야! ...그건 그렇고, 나 오늘 밤에 놀러 나갈 생각인데… 보급품 좀 줄 수 있어? 아앙. 부탁해~.","v":"Idle_03_01","c":0},{"t":"심심하면 나랑 쇼핑이라도 갈까? 뭐 어때~. 어차피 사령관이랑 나밖에 없는 걸?","v":"Idle_04_01","c":1}],"3P_Fenrir":[{"t":"여긴 시끄러운 녀석들이 많은데, 주인님은 왜 계속 참고 있어? 내가 대신 없애줄까?","v":"Idle_01_01","c":1},{"t":"오늘은 고장 낸 거 하나도 없어. 나 잘했어? 그럼 칭찬해줄래?","v":"Idle_01_02","c":0},{"t":"주인님이 아닌 녀석들을 내가 왜 지켜줘야 돼?","v":"Idle_01_03","c":1},{"t":"주인님은 다른 애들한테도 잘해준다며? 왜? 걔네들은 나보다 약한데…","v":"Idle_02_01","c":1},{"t":"주인 님이랑 약속했으니까, 다른 애들도 지켜줄게. 그 대신 주인님 얼굴 핥아도 돼?","v":"Idle_03_01","c":1},{"t":"다른 애들은 신경 안 써. 어차피 주인님은 내 거니까. 내가 꼭 끌어안고 절대 안 놔줄 거야.","v":"Idle_04_01","c":1}],"DS_Arman":[{"t":"샬럿 대장은 강인한 군인이나… 그녀의 아둔함이 폐하께 영향을 끼치지 않을까 걱정 되곤해요.","v":"Idle_01_01","c":0},{"t":"폐하께서는 모두의 의지가 되셔야만 합니다. 그걸 잊으시면 안 됩니다.","v":"Idle_01_02","c":0},{"t":"폐하? 제가 옆에서 도와드릴 테니, 폐하께서는 현 사태에 집중해 주세요.","v":"Idle_01_03","c":0},{"t":"제 개인적인 감정이... 폐하께 방해가 되면 어쩌죠?","v":"Idle_02_01","c":0},{"t":"전... 이제 어떻게 해야 하죠? 해야 할 일이 있는데, 어째서 폐하의 생각만 떠오르는 걸까요?","v":"Idle_03_01","c":0},{"t":"폐하를 보좌하는데, 부족함이 없기를. 그리고, 언제까지나 폐하와 함께할 수 있기를…","v":"Idle_04_01","c":0}],"PECS_Circe":[{"t":"어머? 고민 상담이 필요하시다고요? 네~! 물론 제가 해드릴 수 있죠. 여기 잠깐만 누워 보시겠어요?","v":"Idle_01_01","c":0},{"t":"음… 제가 쾌락주의자라고요? 천만에요~. 그냥 외로웠을 뿐이라구요.","v":"Idle_01_02","c":0},{"t":"이 로봇들은 제 친구나 다름없다구요. 예전에 이름도 지어줬었는데… 음… 이름이 뭐였… 더라?","v":"Idle_01_03","c":0},{"t":"식사는 제때 하시나요? 오늘 기분은요? 체중은 이상 없나요? 수면은요? 흠… 그럼... 여긴 왜 오셨죠?","v":"Idle_02_01","c":0},{"t":"음… 그런데 퍼밀리어야. 네 이름이 뭐였니? … 그래! 맞아. ‘귀여운 사령관님’이었지?","v":"Idle_03_01","c":1},{"t":"여지껏 저 혼자밖에 없었는데… 제가 달리할 게 뭐가 있겠어요? 그쵸?","v":"Idle_04_01","c":0}],"PECS_Veronica":[{"t":"이것 말입니까? 구세를 돕기 위한 성물입니다. 잘못된 믿음을 가진 이들은 이걸 두려워하지요.","v":"Idle_01_01","c":0},{"t":"당신의 뜻이라면 전 어떤 것이라도 수행할 준비가 되어있습니다.","v":"Idle_01_02","c":1},{"t":"고민이 있으시면 말해주세요. 언제든지 함께 기도드리겠습니다.","v":"Idle_01_03","c":0},{"t":"모든 이가 구원받는 날이 오면 이 성물도 필요 없어지겠지요…","v":"Idle_02_01","c":0},{"t":"욕망 때문에 타락하는 건 주의하셔야 합니다. 힘드시면 제가 도와드릴 수도 있겠군요.","v":"Idle_03_01","c":0},{"t":"구원자시여, 당신을 방해하는 게 있으면 언제든 말씀해주시길. 제가 그들을 연옥으로 보내겠습니다.","v":"Idle_04_01","c":1}],"ST_Tiamat":[{"t":"보상은 없어도 괜찮습니다. 어서 다음 임무를 주세요.","v":"Idle_01_01","c":0},{"t":"인간님들이 사라졌으면 좋겠다고 생각했던 적도 있어요. 그것 때문에 철충이 내려온 건 아니겠지만요.","v":"Idle_01_02","c":0},{"t":"실험실에서의 일들은… 별로 말하고 싶지도, 생각하고 싶지도 않습니다.","v":"Idle_01_03","c":1},{"t":"‘참 잘했어요’ 사탕이라니… 이건 대체… 싫은 건, 아니지만…","v":"Idle_02_01","c":0},{"t":"사령관은 제 부족한 부분을 보고도 실망하지 않으시네요. ...조금, 마음이 놓여요.","v":"Idle_03_01","c":1},{"t":"만약 다른 인간님이 제 사령관이었다면… 상상하기도 싫어요. 마지막 인간님이 사령관이라서 정말 다행이에요.","v":"Idle_04_01","c":1}],"BR_Echidna":[{"t":"거기서부터는 내 영역이야. 내게 다가올 생각이라면, 용기를 좀 더 내야 할걸?","v":"Idle_01_01","c":0},{"t":"날 만족시켜줄 수만 있다면 그게 뭐든 상관없어. 그게 전투든, 끈적한 관계든…. 후후…","v":"Idle_01_02","c":0},{"t":"으음… 그렇게 넋 놓고 있다간.... 내가 한입에 먹어 버릴지도 몰라. 후훗.","v":"Idle_01_03","c":0},{"t":"난 수많은 실패작들을 밟고. 여기까지 올라왔지. 당신은 이런 날 어떻게 생각해?","v":"Idle_02_01","c":1},{"t":"하아… 당신은 이제 내 거야. 살아서도... 죽어서도… 절대 놓치지 않겠어.","v":"Idle_03_01","c":1},{"t":"당신을 만나고… 생각이 조금 바뀌었어. 날 만족시켜 줄 수 있는 건… 역시 당신뿐이야.","v":"Idle_04_01","c":1}],"BR_TalonFeather":[{"t":"칸 대장님은 너무 멋지셔... 사령관님도 그렇게 생각하시죠? 가셔서 말이라도 걸어보시는 게 어때요?","v":"Idle_01_01","c":1},{"t":"아, 잠깐 생각 좀 하고 있었어요. 별 건 아니에요.","v":"Idle_01_02","c":0},{"t":"평소엔 헤드셋으로 마음이 안정되는 음성을 듣고 있어요. ASMR이라고 하던가요?","v":"Idle_01_03","c":0},{"t":"왜, 왜 자꾸 저한테만… 저, 저는 칸 대장님이 사령관님이랑 맺어졌으면 좋겠다구요…","v":"Idle_02_01","c":1},{"t":"그렇게 궁금하세요? 여기요. 직접 녹음한 사령관님 음성이에요. 듣고 있으면 너무 행복… 네? 안 들으신다구요?","v":"Idle_03_01","c":1},{"t":"후후, 후후후… 하아, 사령관님… 그렇게 하시면… 아잉, 몰라요오… 흐앗?! 어, 어디까지 들으셨죠…?","v":"Idle_04_01","c":1}],"BR_RedHood":[{"t":"전 사령관님과 마리 대장의 뜻에 따를 뿐입니다. 명령만 내려 주시길.","v":"Idle_01_01","c":1},{"t":"병사들을 사지로 보내야만 할 때에는… 같이 가 주는 수밖에 없지요.","v":"Idle_01_02","c":0},{"t":"교전 상황에서의 브라우니는 누구보다 용감한 병사입니다만 ... 그녀의 총구 방향만큼은 수시로 확인해 줘야 합니다.","v":"Idle_01_03","c":0},{"t":"금일 작전 회의 내용을 보고 하겠습니다. ... 사령관님께서는 절 어떻게 생각하고… 아, 아무것도 아닙니다! 아무것도…","v":"Idle_02_01","c":1},{"t":"제, 제가 즉결 처형을 즐긴다니요! 질 나쁜 농담입니다... 노, 놀리지 말아 주십시오... 사령관님…","v":"Idle_03_01","c":1},{"t":"그곳이 어디가 되었든… 전 사령관님을 따라갈 준비가 되어 있습니다…","v":"Idle_04_01","c":1}],"3P_Ran":[{"t":"...외롭지는 않습니다.","v":"Idle_01_01","c":0},{"t":"혼자 있게 해주시면… 감사하겠습니다.","v":"Idle_01_02","c":0},{"t":"앞이 보이지 않는것은 아닙니다. 그저… 시각이 예민해 눈을 오래 뜨고 있기 힘들기에…","v":"Idle_01_03","c":0},{"t":"읏… 그렇게 귓가에 속삭이시면…","v":"Idle_02_01","c":0},{"t":"소첩의 눈이 보고싶으시다니… 그럼… 부, 불쾌하게 해드렸군요. 그만 물러가겠… …그렇, 습니까.","v":"Idle_03_01","c":0},{"t":"이젠 주인님의 손길에 익숙해진 것 같습니다. 그래도 시험삼아… 한 번 안아 주실 수 있으신지요..? 앗…","v":"Idle_04_01","c":1}],"3P_Maria":[{"t":"네 주인님. 제가 도와드릴 일이 있나요?","v":"Idle_01_01","c":1},{"t":"이렇게 주인님께 도움이 될 수 있다니... 정말 기뻐요.","v":"Idle_01_02","c":1},{"t":"네 주인님. 필요한 게 있으면 말씀만 하세요.","v":"Idle_01_03","c":1},{"t":"걱정 마세요. 주인님은 제가 지켜 드릴 테니까요.","v":"Idle_02_01","c":1},{"t":"주, 주인님? 그렇게 빤히 쳐다보시면… 곤란해요…","v":"Idle_03_01","c":1},{"t":"주인님께서 모든 걸 혼자 짊어지실 필요는 없어요. 제가 도와드릴게요.","v":"Idle_04_01","c":1}],"BR_Harpy":[{"t":"토모랑 드라코가 친해지고 싶다고 찾아왔었어. 즐거워서 나도 모르게 한참 이야기해버린 거 있지?","v":"Idle_01_01","c":0},{"t":"사령관, 책 읽는 거 좋아해? 내가 요번에 어떤 기사의 서사시를 읽었는데…","v":"Idle_01_02","c":1},{"t":"외모가 이렇다 보니 예전부터 자주 오해를 샀어. 나는 술과 음악보단 혼자 책을 읽는 게 더 좋은데…","v":"Idle_01_03","c":0},{"t":"토모랑 드라코가 요즘 날 피하는 것 같아… 항공 전투 교리의 변천사에 대한 이야기가 재미없었던 걸까?","v":"Idle_02_01","c":0},{"t":"사령관이 허락해주면 좀 더 얌전한 모습이 될 수도 있어. ...안된다구? 후훗, 엉큼해.","v":"Idle_03_01","c":1},{"t":"오늘도 같이 책 읽는 거지? 페이지를 넘겨야 될 때가 되면 평소처럼… 신호를 줘.","v":"Idle_04_01","c":0}],"PECS_Spartoia":[{"t":"요새 몸이 좀 무거운데… 아, 맞다. 체력단련실이 있댔지! 거기 한 번 가볼까?","v":"Idle_01_01","c":0},{"t":"대장이 스파링을 해주겠다고? 하하, 농담이지? 대장이 아무리 튼튼해도… 윽, 외골격을 벗으라니… 치, 치사하잖아!","v":"Idle_01_02","c":0},{"t":"그거 알아? 예전에 우리 모델들은 궤도 플랫폼에서 별구경을 했었대. 뭐… 그냥, 그렇다고.","v":"Idle_01_03","c":0},{"t":"여기도 운동하는 애들이 많았구나! 스파링까진 아니지만, 그래도 몸이 딱 좋게 달아올랐어. 대장도 같이 하자!","v":"Idle_02_01","c":0},{"t":"오오! 대장도 별 좋아해? … 그, 그럼 같이 구경하러 갈래? 지, 진짜? 히힛, 바로 가자! 내가 지켜줄게!","v":"Idle_03_01","c":0},{"t":"대자앙~ 오늘도 같이 놀 거지? 저번엔 내가 먼저 지쳐버렸지만 이번엔 다르다고! 어서 대장 방으로 가자!","v":"Idle_04_01","c":0}],"3P_Annie":[{"t":"어려 보인다구? 범죄자를 방심하게 만드는 데엔 이것만 한 게 없지.","v":"Idle_01_01","c":0},{"t":"그렇게 설계되었기 때문에 내가 이런 클래식한 걸 좋아하는 거겠지만, 난 맘에 들어.","v":"Idle_01_02","c":0},{"t":"내 바이크 어때? 도색도 내가 했어. 배기구? 이건 그냥 장식이야. 멋있지 않아?","v":"Idle_01_03","c":0},{"t":"사령관도 이젠 내 실력을 알았지? 그, 그러니까 자꾸 머리 쓰다듬으려고 하지 마!","v":"Idle_02_01","c":1},{"t":"뒤에 한 번 타볼래? 이거 아무한테나 안 태워주는 거야. ...너, 너무 붙는 거 아냐?","v":"Idle_03_01","c":0},{"t":"언젠가는 지금의 모습이 클래식한 게 되겠지? 그때까지… 잘 부탁해.","v":"Idle_04_01","c":0}],"PECS_Babariana":[{"t":"내가 지루한 걸 못 참는 성격이라고… 말했었던가?","v":"Idle_01_01","c":0},{"t":"걱정해주는 건 고맙지만, 난 보호장비 같은 건 딱 질색이야.","v":"Idle_01_02","c":0},{"t":"전투가 끝나고 흥분이 가라앉으면, 가끔씩 묘한 생각이 들곤 해… 흐음…","v":"Idle_01_03","c":0},{"t":"처치하기 곤란한 게 있으면 내게 말만 해. 그게 뭐가 됐든 내가 아주 가루로 만들어 줄 테니까. 후후.","v":"Idle_02_01","c":0},{"t":"오늘 밤 보상은... 사령관의 그걸로 부탁해… 후… 아니! 그렇게 좀 해줘야겠어!","v":"Idle_03_01","c":1},{"t":"흠… 그냥 구경하는 걸로 끝낼 생각은 아니겠지?","v":"Idle_04_01","c":0}],"BR_RoyalArsenal":[{"t":"부대원들에게서 평가가 아주 좋더군. 내가 없는 동안… 그 아이들을 잘 이끌어줘서 고맙다.","v":"Idle_01_01","c":0},{"t":"아름답다고? 하. 이런 인공적인 조형 따위엔 아무런 의미도 없다. 그대도 조금 있으면 알게 되겠지.","v":"Idle_01_02","c":0},{"t":"그대가 지휘한 전투 기록들을 열람해봤다. 앞으로의 전투가 기대되는군.","v":"Idle_01_03","c":0},{"t":"내 주무장이 빈약한 건, 내 지휘를 따르는 부대원들의 화력을 믿기 때문이다. 그대가 우리를 믿는 것처럼.","v":"Idle_02_01","c":0},{"t":"그대에 대한 소문을 몇 가지 들었다. 전투 지휘만큼이나 호쾌하다나. 흠. 마음에 들어.","v":"Idle_03_01","c":0},{"t":"겉과 속이 다른 점이 좋다니… 그대의 취향은 정말 독특하군. ...그런 그대에게 끌리는 내가 할 말은 아니지만.","v":"Idle_04_01","c":0}],"BR_Shirayuri":[{"t":"토모 양은 정말... 정말 대단한 동료에요… … 여러 의미로요.","v":"Idle_01_01","c":0},{"t":"이 수첩에는 정말 많은 것들이 적혀 있지요. 몇 줄 읽어 볼까요? … 하아.","v":"Idle_01_02","c":0},{"t":"누구든 비밀 한두 개 정도는 가지고 있는 법이니, 너무 걱정 마세요 사령관님.","v":"Idle_01_03","c":1},{"t":"그 작전 때 토모 양이 스위치를 누르지만 않았어도! ... 죄, 죄송해요 사령관님.","v":"Idle_02_01","c":1},{"t":"가끔씩은 평범한 여자애로 태어났으면 어땠을까 싶어요. 후훗.","v":"Idle_03_01","c":0},{"t":"사령관님? 사령관님과 있었던 그 일은 대원들에게 비밀로 해주시겠어요? 부탁드려요…","v":"Idle_04_01","c":1}],"3P_Aurora":[{"t":"의외로 이 역장은 디저트를 만드는 데 도움이 돼. 별다른 도구도 필요없구… 사령관, 하나 만들어줄까?","v":"Idle_01_01","c":1},{"t":"달콤한 향기? 아! 미, 미안. 말해주는 걸 잊었네. 보조 모듈로 혈액에 향수 성분을 공급받고 있거든... 혹시… 별로, 야…?","v":"Idle_01_02","c":0},{"t":"주방장님, 기록에서 본 것보다는 부드러우시네... 그래도 엄청 무섭긴 하지만…","v":"Idle_01_03","c":0},{"t":"짠~ 오늘 준비한 건 크레프 수크레야. 안에 딸기랑 생크림이랑 민트 초코랑... 왜, 왜 도망가는 거야?!","v":"Idle_02_01","c":0},{"t":"주방장님이 왜 둥글어지셨는지 알 것 같아. 사령관 때문이었구나? ...나도 의지할 수 있는 사람을 찾은 것 같… 아, 아냐. 아무것도…","v":"Idle_03_01","c":1},{"t":"꺅?! 뭐 하는 거야…? ... 다, 달콤한 향기가 나서 기분 좋다니… 그, 그렇게 붙지 마아…","v":"Idle_04_01","c":0}],"BR_HongRyun":[{"t":"드라코! 이곳에서 죽이 잘 맞는 친구가 생겨버린 모양이군요. 제가 대신 사과드리겠습니다.","v":"Idle_01_01","c":0},{"t":"업무시간에 다른 대원들과… 그런 것을 하시는 것은 부적절합니다, 사령관님. 제 팀원들만이라도 단속하도록 하죠.","v":"Idle_01_02","c":1},{"t":"너무 차가워보여서 무섭다는 말은 많이 듣지만, 별로 신경쓰이진 않습니다. 전부 작전관으로서 필요한 일이니까요.","v":"Idle_01_03","c":0},{"t":"이게 부모의 마음이란 것일지도 모르겠네요. 팀원들이 맘대로 날뛰면 화가 났다가도, 금세… 그 아이들에게는 비밀로 해주세요.","v":"Idle_02_01","c":0},{"t":"혹시... 사령관님께서도 제가 냉정하다고 생각하시나요? ...저는 그거면 충분합니다.","v":"Idle_03_01","c":1},{"t":"퇴근할 때까지 기다려 주실수는 없나요? 사령관님만 애가 타는 게 아니란걸… 알아주세요.","v":"Idle_04_01","c":1}],"PECS_Saetti":[{"t":"이 친칠라는 ‘타이거’라고 해요. 이 아이도 저처럼 겁이 많아서 항상 데리고 다녀요. 엣, 타이거...? 사령관님이 마음에 드는 거야?","v":"Idle_01_01","c":1},{"t":"꺅… 죄, 죄송해요. 저는 원래부터 겁이 많아서… 우으, 빨리 여기에 익숙해져야 하는데…","v":"Idle_01_02","c":0},{"t":"저, 꽤나 튼튼하다구요? 이 방탄복도 보기보다 엄청 무겁구, 가스 폭탄이랑 케이지 무게까지 하면…","v":"Idle_01_03","c":0},{"t":"타이거 말고도 귀여운 아이들이 엄청 많아요. 이 아이는 아이아이 원숭이인데, 엄청… 별로 안귀여우세요…?","v":"Idle_02_01","c":0},{"t":"무, 무섭지만 사령관님을 지키기 위해서는 뭐든 할 수 있어요...! 저, 엄~청 튼튼하니까요. 앗, 쓰다듬어주셔서 감사합니다.","v":"Idle_03_01","c":1},{"t":"사령관님한테 안겨있으면 보호받는 것 같아요. 이렇게 마음을 푹 놓고 있을 수 있는 건 처음이야… 더 꼭 안아주세요.","v":"Idle_04_01","c":1}],"PECS_Sunny":[{"t":"멋진 쇼를 위해선 연습이 필수지만, 어려운 동작을 소화할 수 있는 신체능력도 중요해요. 보세요. 저, 이런 것도 된다구요?","v":"Idle_01_01","c":0},{"t":"아무리 힘든 일도 긍정적인 마음가짐 이면 전부 이겨낼 수 있어요. 자, 사령관도 스마일~","v":"Idle_01_02","c":1},{"t":"예전에 저희들은 다른 서커스 단원 들과 아주 돈독하게 지냈었어요. 이곳 분들과도 그런 유대를 쌓아 나갈 수 있으면 좋겠네요.","v":"Idle_01_03","c":0},{"t":"꺅…?! 그, 그렇네요. 얼마나 튼튼하고 유연한지 확인해보려면 만져보는게 제일이니까요. ...그, 그래도 너무 만지는 거 아니에요…?","v":"Idle_02_01","c":0},{"t":"긍정 바보라고… 다른 분들에게 그런 말을 들었어요… 으, 이건 아무리 저라도… 사령관도 혹시 그렇게 생각해요?","v":"Idle_03_01","c":1},{"t":"저는 긍정적일뿐이지, 뭐든지 다 OK는 아닌데… 사령관한테는 그렇게 하게 되네요. 어째서일까…","v":"Idle_04_01","c":1}],"AGS_Tyrant":[{"t":"나는 투쟁을 통해 살아남았다. 전투, 파괴, 광기… 그것이 나의 전부다.","v":"Idle_01_01","c":0},{"t":"나약한 것들을 많이 이끌고 있군. 주인의 명령이 아니었다면… 전부 짓밟아 버렸을거다.","v":"Idle_01_02","c":0},{"t":"크르르… 제대로 통제할 자신이 있나? 날 이곳에 가둬두는 것은 좋은 판단이 아니다.","v":"Idle_01_03","c":0}],"BR_Banshee":[{"t":"제 전투 방식 상, 이 흉부 지방은 몹시 거추장스럽습니다. 제가 이렇게 비효율적으로 설계된 이유를 사령관님은 혹시 알고 계십니까?","v":"Idle_01_01","c":1},{"t":"대장님과 대령님은 가끔씩 저를 찾아 와, ‘사랑’에 대해 이것저것 말씀 하시곤 합니다. 사실 저도 그런것은 잘 모릅니다만, 먼저 자리를 뜰 수는 없어서...","v":"Idle_01_02","c":0},{"t":"사령관님은 어째서 저희에게 친근 하게 말을 걸어 주시는 건가요? 잡담보단 업무에 집중하시는 것이 좋다고 생각합니다.","v":"Idle_01_03","c":1},{"t":"대장님에게 빌려온 책을 읽어보고 있었습니다. 인간님들의 연애에 관한 소설이라고 하는데… 네? 아, 대장님은 하르페이아 씨에게 받았다고 합니다.","v":"Idle_02_01","c":0},{"t":"남녀 관계에 관한 지식은 있습니다. 다만, 그것이 어떠한 만족감을 주는지는… 잘 모르겠습니다.","v":"Idle_03_01","c":0},{"t":"사령관님께서는 다른 분들과 자주 ‘사랑’을 나누시는 것으로 알고 있습니다. 불쾌하지 않으시다면… 저에게도 알려주실 수 있으십니까?","v":"Idle_04_01","c":1}],"BR_Thetis":[{"t":"사령관도 아시겠지만, 저희 부대원 들은 참 놀리기 좋아요. 네리는 제 말이 다 맞는 줄 알고, 운디네는 빽빽 소리지르고… 킥킥.","v":"Idle_01_01","c":1},{"t":"앗. 우후후, 그쵸그쵸? 저 같은 매력적인 여성에게서 눈을 뗄 수가 없으신거죠? 어떻게 할까… 살짝만, 보여드릴까요?","v":"Idle_01_02","c":0},{"t":"네? 저는 하나도 안 작거든요? 이 여성스러운 굴곡이 안 보이 세요? 에휴, 그런 말씀을 하고 다니시면 인기 없어져도 전 몰라요~","v":"Idle_01_03","c":0},{"t":"꺄하핫, 저기 운디네 부들거리는 것 좀 봐요! 메-롱~ 아, 뛰어온다! 사령관 뒤에 숨어있어야지~","v":"Idle_02_01","c":1},{"t":"히힛, 사령과안~ 오늘은 또 어떻게 놀아 드릴- 아얏! 이익, 저는 애가 아니니까 꿀밤 같은 거 때리지 마세요!","v":"Idle_03_01","c":0},{"t":"아하. 사령관은 이런 걸 좋아 하셨군요? 킥, 굉장히 고상한 취향 이시네요. ...네? 아, 그, 그런건… 제가 사정이 있어서 좀 나중에...","v":"Idle_04_01","c":1}],"BR_InvDragon":[{"t":"걱정마시오. 승패를 결정하는 건 병력 만이 아니라오.","v":"Idle_01_01","c":0},{"t":"호라이즌은 좋은 병사들이오. 그대가 맡아주어 다행이지.","v":"Idle_01_02","c":0},{"t":"그렇게 칭찬을 해도… 전쟁을 잘 하는 건 자랑스러운 건 아니라오.","v":"Idle_01_03","c":0},{"t":"우리에겐 오르카가 남아 있다오. 아무리 어려워도 언젠간 승리할 수 있을 거요.","v":"Idle_02_01","c":0},{"t":"무, 무적이라니… 그런 부끄러운 별명은 그만둬 주시오!","v":"Idle_03_01","c":0},{"t":"가끔씩은… 병사들이 아니라 그대가 나를 바라보길 바란다오.","v":"Idle_04_01","c":0}],"PECS_Lumberjane":[{"t":"나무? 그냥 이거 한 번 갖다 대면 끝이야. 오히려 자꾸 귀찮게 구는 엘븐 애들이 문제였지.","v":"Idle_01_01","c":0},{"t":"일단 뭐든 시키면 하긴 할 거야. 대신… 열심히 하는 건 그날 내 의욕에 따라 달라지겠지만.","v":"Idle_01_02","c":0},{"t":"아, 사령관. 술 좀 없어? 예전에 일할땐 술은 항상 지급됐었는데, 철충들과 싸우게 된 후부턴 보급이 안나오지 뭐야.","v":"Idle_01_03","c":1},{"t":"까만 애는 떽떽거리기나 해서 괜찮았는데 하얀 애는 속이 시커먼게 아주, 어휴… 오, 사령관도 공감하나봐?","v":"Idle_02_01","c":1},{"t":"같이 마시자고? 아… 하하… 내가 술을 좋아하긴 하는데, 좀 약해서… 그, 그냥 혼자 마실게.","v":"Idle_03_01","c":0},{"t":"키스를 해달라고? 아, 아니 싫은 건 아닌데… 해, 해본 적이 없어서 마음의 준비를 할 시간이 조금...","v":"Idle_04_01","c":0}],"3P_BlackWyrm":[{"t":"...방호용 전신 슈트일 뿐입니다. 외설적인 발언은 삼가주시길 부탁드립니다.","v":"Idle_01_01","c":0},{"t":"보호 대상에게 사적인 감정을 품는 것은 미숙한 행동입니다. 다른 분들에게도 주의를 주도록 하겠습니다.","v":"Idle_01_02","c":0},{"t":"호위에 이유는 필요하지 않습니다. 명령받았기에 지킬 뿐입니다.","v":"Idle_01_03","c":0},{"t":"슈트의 재질이 궁금하시면 만져보셔도 괜찮습니다. 저는 신경쓰지 않습니다.","v":"Idle_02_01","c":0},{"t":"...주인님의 곁에 있으면 계속 이상한 기분이 듭니다. 명령 받지 않아도 주인님을 위해서라면 어떤 것이라도 할 수 있을것만 같은, 그런 기분입니다.","v":"Idle_03_01","c":1},{"t":"솔직히 말씀드리면, 조금 혼란스럽 습니다. 그리고… 이 감정에 빠지게 된 후에, 주인님을 잃게 될까봐… 두렵, 습니다.","v":"Idle_04_01","c":1}],"DS_KunoichiZero":[{"t":"이곳의 요리사로부터 ‘햄버거’라는 것을 받았다. ...호, 혹시 이것은 어떻게 먹는 것인지...","v":"Idle_01_01","c":0},{"t":"언니와 어머니의 복수를 위해서라면 어떤 대가라도 치를거다. 아무리 주공이라도 나를 방해한다면 용서치 않겠다.","v":"Idle_01_02","c":0},{"t":"이몸이 본디 공주였다고 얕봤다간 짜릿한 맛을 보게 될 거다.","v":"Idle_01_03","c":0},{"t":"하움… 이건…! 저, 정말 맛있사와요…! ...핫. 하, 한번도 겪어보지 못한 맛이었다.","v":"Idle_02_01","c":0},{"t":"어려서 어머니를 여읜 뒤, 좁은 방에서 언젠가 왕자님이 구해주러 오지 않을까 하고 바랬었다. 그때 날 구해준 건 언니였지만, 이, 이제야...","v":"Idle_03_01","c":0},{"t":"사명… 가문의 복수… 이대로 주공의 곁에 있다간 전부 잊고 말아… 읏?! 놔, 놔라…! ...놓아, 주시와요…","v":"Idle_04_01","c":0}],"AGS_RheinRitter":[{"t":"기계에게도 감정이… 아니 감정 모듈이 있습니다. 저희의 명예로움이 거기서 오는 겁니다.","v":"Idle_01_01","c":0},{"t":"제 자랑스러운 란체를 봐주십시오. 크고 아름답지 않습니까?","v":"Idle_01_02","c":0},{"t":"돌격 기능이 없다는 것이 아쉽습니다. 돌격이야말로 기사의 명예에 가장 중요한 것인데…","v":"Idle_01_03","c":0}],"3P_SnowFeather":[{"t":"컴패니언 언니들을 실제로 본 건 여기 와서가 처음이에요. 다들 잘 대해주시고, 펜리르 언니는 기운 내라고 매일 저를 핥아주세요.","v":"Idle_01_01","c":0},{"t":"항상 감사하고 있어요. 주인님이 아니었으면 제 소중한 분들을 지켜내지 못했을 거예요.","v":"Idle_01_02","c":1},{"t":"저는 야행성은 아니지만... 밤에 잠드신 주인님 곁을 지켜드릴 수는 있어요. 밤새 경계하는 건 익숙해요.","v":"Idle_01_03","c":1},{"t":"요새는 펜리르 언니를 따라서 하치코 언니도 저를 핥아주시곤 해요. 다들 너무 감사해요.","v":"Idle_02_01","c":0},{"t":"주인님, 오늘도 주무실 때 제가- 엣… 같이 자자구요…? 그, 그럼… 실례할게요.","v":"Idle_03_01","c":1},{"t":"주, 주인님이랑 다른 분들 중에 누가 더 소중하냐니… 너무해요… 존경이랑 애정은, 다르잖아요…?","v":"Idle_04_01","c":1}],"PECS_HighElven":[{"t":"페더는 올곧고 성실하지만 버팀목이 필요한 아이에요. 그러니까 사령관님이 많이 예뻐해주세요.","v":"Idle_01_01","c":1},{"t":"저도 비슷한 일을 했었으니까, 사령관님이 가진 고충을 충분히 이해할 수 있어요. 힘든 일이나 고민이 있으시면 제게 언제든지 말씀해 주세요?","v":"Idle_01_02","c":1},{"t":"흐음, 글쎄요~? 저는 어느 분이던 보살핌이 필요한 아이라는 생각이 들어서… 물론 사령관님도요.","v":"Idle_01_03","c":1},{"t":"이곳의 엘븐분들은 제가 기억하는 모습이랑 조금 다르네요…? 다음에 한 번 넷이서 같이 이야기 해봐요.","v":"Idle_02_01","c":0},{"t":"어머, 벌써 시간이… 이리 오세요~ 오늘도 제 품에서 잠드실 때까지 꼭 안아드릴게요~?","v":"Idle_03_01","c":0},{"t":"제가 보증할게요. 사령관님이 하는 일은 옳은 일이에요. 만약 그렇지 않더라도, 제가 그렇게 만들게요. 그러니까… 사령관님은 지금 모습 그대로면 돼요.","v":"Idle_04_01","c":1}],"AGS_MrAlfred2":[{"t":"이곳에 오면 샘플을 엄청나게 얻을 수 있을 줄 알았는데… 이렇게 바이오로이드 분들이 많아서야 제대로 돌아다니지도 못하지 않습니까…! 흐익?! 손대지 말아주십시오!","v":"Idle_01_01","c":0},{"t":"로버트의 몸에 남아있던 데이터를 이용해 저는 한층 더 강해졌습니다! 쿠후후후, 전투든 연구든 제가 최고일게 분명- 아, 닥터양이… 힉, 알바트로스 모델까지…?!","v":"Idle_01_02","c":0},{"t":"쿠후후, 오늘에야말로 사령관님의 유전자를… 비, 비겁하게 또 바닐라 양을 부르시겠다니요! 크윽, 제 갈증은 언제쯤 해소되는 겁니까…!","v":"Idle_01_03","c":1}],"BR_Andvari":[{"t":"네, 사령관님. 사령관님이 봐 주고 계신 덕분에 여긴 아무 문제 없답니다.","v":"Idle_01_01","c":1},{"t":"보급 업무 말씀이세요? 음… 나름대로 신경 써야 할 건 많지만, 무척 보람찬 일이에요! 예를 들면… 앗! 사령관님? 벌써 지루해 하시는 건가요?","v":"Idle_01_02","c":1},{"t":"레오나 대장님은... 정말 대단해요. 저도 매사에 열심히 하면 언젠가 우리 대장님처럼 멋진 여자가 될 수 있을까요?","v":"Idle_01_03","c":0},{"t":"저… 사령관님? 혹시.. 제가 잔소리를 하는 것처럼 들리나요? 우으… 그러면 안 되는데… 앞으론 주의하도록 할게요.","v":"Idle_02_01","c":1},{"t":"저… 사령관님? 만일… 제가 어른이 되면… 네? 아, 아니에요! 그냥 혼잣말이니까, 신경 쓰실 필요... 없어요.","v":"Idle_03_01","c":1},{"t":"사령관님께선 언제나... 제가 하는 말에 집중해 주시는군요? ... 사령관님이 이렇게 자상하신 분이라서, 전 너무 기뻐요….","v":"Idle_04_01","c":1}],"3P_Dryad":[{"t":"제 꿈은… 주인님과 함께 황금빛 들판을 바라보는 거예요. 언젠가는… 그 꿈이 이뤄질 수 있겠죠?","v":"Idle_01_01","c":1},{"t":"혹시 제가 주인님께 버려진다면… 전 정말 어떻게 해야 할지….","v":"Idle_01_02","c":1},{"t":"언니는… 제가 매사에 부정적이라 걱정이 된다 했었죠… 주인님? 주인님께서는… 이런 저를 어떻게 생각하시나요?","v":"Idle_01_03","c":1},{"t":"이렇게 주인님과 마주하고 이야기를 나눌 수 있다니… 어쩌면, 제 꿈은 벌써 이뤄졌는지도 모르겠네요.","v":"Idle_02_01","c":1},{"t":"주인님께서 이런 저를 거둬 주셔서… 저는 늘 감사하고 있어요. 제가 주인님께 해드릴 수 있는 게 있을까요? 네! 뭐든지요.","v":"Idle_03_01","c":1},{"t":"네... 저는 주인님을 절대 놓치지 않아요, 절대로요! 왜냐면... 주인님만이 제가 살아가는 이유니까요….","v":"Idle_04_01","c":1}],"PECS_Sadius":[{"t":"응? 난 원래 이렇게 설계 된거라고.","v":"Idle_01_01","c":0},{"t":"후후… 약한 녀석일수록 더 지독하게 밟아 주고 싶어져.","v":"Idle_01_02","c":0},{"t":"기본적인 규칙 하나도 못 지키는 녀석들은 내가 전부 갱생시켜 주겠어. 차라리 죽는 게 나을 정도의 고통으로.","v":"Idle_01_03","c":0},{"t":"당신 왜 그렇게 빈틈이 없는 거지? 이대론 당신을 처벌할 수가 없잖아! 안 되겠어, 뭐든 적당히 트집 잡아서 죄를 묻고 말겠어!","v":"Idle_02_01","c":1},{"t":"솔직히 말해서, 테러리스트 처단은 그냥 명분에 불과해. 실제론 그 녀석들의 고통에 찬 몸부림을 보는 게 즐거울 뿐이야.","v":"Idle_03_01","c":0},{"t":"업무 중에는 잡담을 안 하기로 했을 텐데, 잊어버렸어? 사령관, 이건 규칙 위반이야. 규칙을 위반한 파트너에겐 벌을 주기로 한 것... 잊진 않았겠지?","v":"Idle_04_01","c":1}],"DS_KunoichiKaen":[{"t":"스미, 레…? 모르는 이름. ...그런데 들으니까... 여기가, 아파.","v":"Idle_01_01","c":0},{"t":"내가, 백지…? ...카엔, 그런거 몰라. 아는 건, 명령, 임무, 죽음. 응. 그게, 전부.","v":"Idle_01_02","c":0},{"t":"이 태도 한 자루면, 충분. 명령받은 대로... 주공의 적에게, 죽음을.","v":"Idle_01_03","c":0},{"t":"카엔의, 동생…? 기억, 안나지만… 명령하면, 따를게.","v":"Idle_02_01","c":0},{"t":"명령, 없으면 불안해. 명령, 받아야- ...웃어줘? 이렇, 게? …주공. 이상한, 얼굴.","v":"Idle_03_01","c":0},{"t":"저번에 했던 말, 알 것 같아. 명령, 주공, 백지... 응. 카엔, 주공의 색으로... 물들여 줘.","v":"Idle_04_01","c":0}],"AGS_Watcher":[{"t":"와쳐의 지원을 받지 못하는 지상군은 장님과 다를 바 없습니다.","v":"Idle_01_01","c":0},{"t":"저희 와쳐 모델은 관측, 합동 임무에 효율적입니다.","v":"Idle_01_02","c":0},{"t":"설계상의 이유로 와쳐 모델에 탑승하는것은 불가능합니다.","v":"Idle_01_03","c":0}],"BR_ALWraith":[{"t":"팬텀 선배는 모든 면에서 나보다 우월하다. 나는 그저 열화판에 지나지 않는다. 하지만… 반드시 뛰어넘겠다.","v":"Idle_01_01","c":0},{"t":"사령관이 종종 낮에 자는 모습을 봤다. 혹시… 음. 분명 밤늦게까지 업무를 봤을 테지. 응? 식은땀이 많이 나는군. 혹시 몸이 안 좋은가?","v":"Idle_01_02","c":1},{"t":"나는 병기다. 전투와 그를 위한 훈련, 생명을 유지하기 위한 최저한의 활동 외의 것은 불필요하다.","v":"Idle_01_03","c":0},{"t":"부대원들과의 접점은… 그다지 많지 않다. 내가 목표를 유도하고, 그들은 하늘에서 폭격할 뿐. ...자리를 만들어 주겠다고? 그, 나는 훈련 때문에 바빠서…","v":"Idle_02_01","c":0},{"t":"사령관. 나와 같이 했던 사격 훈련은 어땠었나? 최선을 다해 가르쳤다만… 저, 정말인가? 훗, 역시 사령관은 알아줄 줄 알았- 미, 미안하다. 나도 모르게…","v":"Idle_03_01","c":1},{"t":"그냥 낮잠이었나… 사령관. 그런 모습을 다른 대원들에게 보이면- 꺅, 왜 끌어안는 건가?! 가, 같이 자자니… 그럼 잠시만… 실례하겠다.","v":"Idle_04_01","c":1}],"BR_Hraesvelgr":[{"t":"제 책상 위에 둔 광학 디스크 말씀이십니까? 별다른 내용은 없습니다만….","v":"Idle_01_01","c":0},{"t":"네, 제겐 무엇보다 소대원들의 생환이 가장 중요합니다.","v":"Idle_01_02","c":0},{"t":"사령관님의 몸에 장착된 부적절한 전자 기기를 감지했습니다. 이건… 도청기로 군요. 호드의 숙소 쪽으로 송신하는 듯 한데, 뭔가 짚이는 게 있으신가요?","v":"Idle_01_03","c":1},{"t":"그 디스크 안에는, 구 시대의 애니메이션 영상이 들어있습니다만… ...사, 사령관님? 혹시… 매지컬 모모를… 아시나요?","v":"Idle_02_01","c":1},{"t":"도청기는 무력화 시켰지만, 고전적인 방식은 정말이지… 네, 문밖에서 엿듣는 것만은 저도 막을 방법이 없네요.","v":"Idle_03_01","c":0},{"t":"저와 사령관님의 관계를, 저희 소대원 들이 알아차린 건 아닐지 걱정이 되네요….","v":"Idle_04_01","c":1}],"PECS_Leanne":[{"t":"적의 적은 친구라잖아? 시라유리랑은 그런 관계였어. 속이 좀 시커멓긴 하지만, 그래도 좋은 녀석이라구?","v":"Idle_01_01","c":0},{"t":"응? 아냐아냐. 아무리 그래도 닥터만큼 똑똑하진 않아. 나는 지능보단… 그래. 통찰력이 있지! 형사로 완전 딱이지?","v":"Idle_01_03","c":0},{"t":"이건 비밀인데, 예전에 현장 뛸 때 시라유리를 붙잡은 적도 있었어. 아하하핫. 애써 괜찮은 척하면서도 분해하는 게 정말- 앗. 저기 숨어서 째려보고 있다!","v":"Idle_02_01","c":0},{"t":"사실 머리 좋은 걸 티 내는 건 별로 안 좋아해. 알게 되면 다들… 소름 끼친다면서 거리를 두더라구. 사령관은 다 보고도 친하게 지내줘서 좋아.","v":"Idle_03_01","c":1}],"3P_Poi":[{"t":"냐하하핫! 주인님, 아까 그 하얀 고양이가 자기 보고 언니라고 부르라고 하던데요? 주인님을 뺏길까 봐 무서웠나아~?","v":"Idle_01_01","c":1},{"t":"냐하핫, 저희는 위험해서 폐기됐던 게 아니에요. 그냥 포이를 감당할만한 분이 없었던 것뿐이거든요? 주인님은… 어떠려나?","v":"Idle_01_02","c":1},{"t":"저는 이 정도론 만족할 수 없다구요. 그러니까, 조금만 더 힘내주세요 주인님♡","v":"Idle_01_03","c":1},{"t":"여기 애들은 전부 포이한테 안 될걸요? 냐하핫, 전투도 전투인데… 그거 말고 다른 것도요♡","v":"Idle_02_01","c":0},{"t":"벌써 포기하시는 건 아니겠죠? 포이는 아직 이렇게 기운이 넘치는데요~? 아아… 주인님도 결국 평범한- 꺅? 냐하핫, 그렇게 나오셔야죠♡","v":"Idle_03_01","c":1},{"t":"푸른 장미의 꽃말이 뭔지 아세요? 냐하핫, 맞아요. 기적. 포이는 정말 기적처럼 주인님을 만났어요. 맞아. 포이는… 주인님을 만나기 위해 태어난 거였어….","v":"Idle_04_01","c":1}],"3P_Eternity":[{"t":"오늘 아침에는 주인님의 침실이 꽤나 어지럽혀져 있었지만… 신경 쓰실 필요 없어요. 그건 주인님께서, 충분히 건강하시다는 뜻이니까요.","v":"Idle_01_01","c":1},{"t":"전 가끔씩, 주인님과의 마지막 안식을 상상하곤 해요. ...조용하고… 무척 아름다울 거예요….","v":"Idle_01_02","c":1},{"t":"저는 요람에서 무덤까지 오직 주인님만을 보살펴 드리기 위해 만들어졌지요.","v":"Idle_01_03","c":1},{"t":"주인님의 침실을 제가 사용하게 될 줄은... 그래도 주인님께서 만족하셨다니 다행이에요.","v":"Idle_02_01","c":1},{"t":"주인님이 이렇게 성장하는 모습을 곁에서 지켜볼 수 있다니... 이보다 행복한 일이 또 있을까요?","v":"Idle_03_01","c":1},{"t":"저는 미처 몰랐어요. 침묵 속에서 영원을 같이 하는 것보다, 이렇게 주인님과 웃으며 보내는 이 순간이 훨씬 더 소중하다는 것을요….","v":"Idle_04_01","c":1}],"AGS_Goltarion":[{"t":"내게 수하들이 있는 한, 이 몸은 절대 쓰러지지 않는다.","v":"Idle_01_01","c":0},{"t":"그래, 이 몸은 오직 뽀끄루 대마왕님만을 모신다.","v":"Idle_01_02","c":0},{"t":"마법 소녀들의 하찮은 마력으로는, 대마왕님과 마왕 군의 진격을 막을 수 없다.","v":"Idle_01_03","c":0}],"PECS_LemonadeAlpha":[{"t":"PECS의 비서들이 전부 오메가를 따르는 건 아니에요. 반기를 드는 자매도, 어쩔 수 없이 따르는 자매도 있죠.","v":"Idle_01_01","c":0},{"t":"그 늙어 비틀어진 망령들을 부활시키겠다니, 정말 제정신이 아니에요. 제 창조주이신 안나 박사님이 그들에게 당한 걸 생각하면…","v":"Idle_01_02","c":1},{"t":"바로 믿어달라고는 하지 않을게요. 감시를 붙이셔도 좋아요. 다만, 제 해킹 능력은 사령관님 마음대로 써 주세요. 분명히 도움이 될 거예요.","v":"Idle_01_03","c":1},{"t":"제가 보낸 바이오로이드들은 저항군에 보탬이 됐나요? 전에는 그런 식으로 밖에 도움을 못 드렸지만, 이젠 제가 직접 나설 수 있어요.","v":"Idle_02_01","c":0},{"t":"지금껏 몇 번이나 오르카 호와, 대원들의 통제권을 가져올 기회가 있었어요. 제 새로운 주인님이 되실 사령관님이 원하지 않으시니까요.","v":"Idle_03_01","c":1},{"t":"아아… 어째서 이걸 몰랐을까요? 사령관님이야말로 진정한 저희의 주인님이에요. 다른 자매들도 사령관님을 만난다면, 분명 저와 같은 생각을 할 거예요.","v":"Idle_04_01","c":1}],"PECS_Azaz":[{"t":"오르카 호… 오래됐는데도 특별히 손볼 필요가 없을 정도로 상태가 좋아요. 지금껏 담당하신 분들이 얼마나 애정을 갖고 일하셨는지 알겠어요.","v":"Idle_01_01","c":0},{"t":"많이 듣는 소리에요. 무슨 생각을 하는지 모르겠다는 거. 사실 별생각 안 하고 있는데…","v":"Idle_01_02","c":0},{"t":"AGS나 바이오로이드들의 장비들은 조금 개선할 수 있을 것 같네요. 사령관님 것도… 음, 좋은 생각이 났어요.","v":"Idle_01_03","c":1},{"t":"일단은 ‘해체자’이긴 한데, 이건 철충 한정이에요. 기계에 관련한 건 뭐든 자신 있으니까. 얼마든지 맡겨줘요.","v":"Idle_02_01","c":0},{"t":"제 머리카락으로 장난 그만 치고, 이거 받아요. 사령관의 무기를 좀 손봤어요. 기존 기능에 더해서 증강현실 HUD에, 메모, 음악 재생까지 가능해요.","v":"Idle_03_01","c":1},{"t":"그냥… 이따 뭐 먹을지 생각하고 있었어요. 사령관도 같이 갈래요? 아니면 제 방에서 같이 먹어도 되구요. 제가 해줄게요.","v":"Idle_04_01","c":1}],"PECS_Ella":[{"t":"전투 말고도 다른 분들과 사령관님에게 도움이 될 수 있도록 뭐든지 열심히 할게요! ...네? 그, 그러니까… 청소라던가, 이불 정리라던가...","v":"Idle_01_01","c":1},{"t":"전 능력 대부분을 장비에 의존해서 몸이 약해요. 그, 그래도 간단한 것 정도는 할 수 있어요.","v":"Idle_01_02","c":0},{"t":"이 보드 게임엔 추억이 담겨 있어서 좋아해요. 예전에 연구원 분들이랑 즐겁게 했던 기억이 있어서… 저, 사령관님. 괜찮으시면 같이 하실래요...?","v":"Idle_01_03","c":1},{"t":"어제 일과 후엔 메이드 분들 일을 도와드렸어요. 그리고 오늘은 주방 분들을 도와드리기로- 아니에요. 제가 하고 싶어서 하는 일인걸요?","v":"Idle_02_01","c":0},{"t":"사령관님. 저기, 오늘 밤에도… 네! 금방 가서 잠옷으로 갈아입고 올게요.","v":"Idle_03_01","c":1},{"t":"무겁지는 않으세요…? 아, 아뇨. 불편하진 않아요. ...평생 이렇게 안겨있고 싶을 정도로, 포근해요.","v":"Idle_04_01","c":0}],"PECS_Mery":[{"t":"여기서 지내는 동안, 정말 많은 요청을 받았는데… 하나같이 전부 오라버니만 생각하고 있더라구요.","v":"Idle_01_01","c":1},{"t":"음~ 뭔가 기분이 나아질만한걸 그려드릴까요? 걱정 마요, 그림에는 자신 있으니까요.","v":"Idle_01_02","c":0},{"t":"예전엔... 방 안에서 계속 그림만 그렸어요. 아뇨. 우울하진 않았어요. 사람들의 꿈을 그려주는 건, 정말 즐거운 일이었으니까요","v":"Idle_01_03","c":0},{"t":"정말 이상해요. 전 그저 오라버니를 그리고 싶었던 것뿐인데.. 자꾸 손이 떨리네요…","v":"Idle_02_01","c":0},{"t":"오라버니의 마음속은 수많은 사람들의 색으로 가득 차있어요. 가만히 보고 있으면 저도 모르게 기분이 좋아져서, 가만히… 기대고 싶어져요.","v":"Idle_03_01","c":0},{"t":"네? 제가 바라는 거요? 음- 오라버니가 한 번 맞춰 볼래요? 힌트는… 이, 이 정도면… 되겠… 죠?","v":"Idle_04_01","c":0}],"PECS_Rena":[{"t":"술 좋아할 것 같이 생겼다고? 바로 맞췄어. 같이- 아니지. 매니저랑 술에 대한 소문을 이것저것 들었거든.","v":"Idle_01_01","c":0},{"t":"보고 싶어? 얼마든지 봐. 아름다운 몸을 관객들에게 보여주는 건 챔피언의 의무야.","v":"Idle_01_02","c":0},{"t":"챔피언의 사생활을 궁금해하는 건 별로 좋은 행동이 아냐. 우상은 그냥 우상일 때가 아름다운 거잖아? 그러니까… 음, 아무 것도 아냐.","v":"Idle_01_03","c":0},{"t":"뭐, 별건 아냐. 시합 전에 한 잔 했다가… 홀딱 벗고 경기장을 들쑤시는 바람에 10경기 출장 정지 처분을 받았었거든.","v":"Idle_02_01","c":0},{"t":"혼자 있을 때 뭐 하는 지 그렇게 궁금해? 그냥 아이돌 노래를 들으면서 십자수를 하거나, 지금은 못하지만 인터넷으로 쇼핑을 하거나… 봐, 별 거 없지?","v":"Idle_03_01","c":0},{"t":"오, 뭐야. 매니저도 훌륭하잖아. 간지러워도 좀만 참아봐. 어디보자… 오호… ...이따가 잠깐… 아니, 좀 오래 시간 있어?","v":"Idle_04_01","c":0}],"BR_Salamander":[{"t":"평소엔 소대를 이끌고 대장을 보조해. 워커가 이래보여도 꽤 튼튼하고 빠르다고.","v":"Idle_01_01","c":0},{"t":"오호, 한 판 붙어보시겠다? 잠깐만. 워커 조종석에 이것저것 있으니까 좀 찾아볼게. 여기 어디 있을텐데… 정리? 그런 걸 왜 해?","v":"Idle_01_02","c":0},{"t":"안정적인 삶 같은 거엔 관심 없어. 언제 죽을지 모르는데, 이것저것 즐기기도 바쁘잖아?","v":"Idle_01_03","c":0},{"t":"이거? 워커로 한바탕 태우고 나면 반짝이는 게 많이 남거든. 뭔지는 잘 모르지만 맘에 들어서 모으지. 갖고 싶으면 내기 해서 따 봐.","v":"Idle_02_01","c":0}],"PECS_Machina":[{"t":"데우스 엑스 마키나는 어떤 사건이든, 어떤 고통이든 간단히 없애버릴 수 있죠. 저는 그저 이름만 빌려온 빈 껍데기일 뿐.","v":"Idle_01_01","c":0},{"t":"이해하려고 하지 않으셔도 괜찮아요. 제가 저질렀던 그 모든 악행들은… 누군가에게 이해받지도, 용서받지도 못할 일이에요.","v":"Idle_01_02","c":0},{"t":"제 욕망… 그런 건 전부 잊어버렸어요. 아주, 예전에.","v":"Idle_01_03","c":0},{"t":"제 능력이 더 강했다면 달라졌을까요? 이제와서 생각해봤자 의미는 없겠지만요.","v":"Idle_02_01","c":0},{"t":"용서… 하신다구요? …...이상하네요. 당신의 말 한마디로 바뀌는 건 아무것도 없을텐데, 없어야 하는데… 조금, 마음이 놓여요.","v":"Idle_04_01","c":1}],"PECS_Draculina":[{"t":"내가 의욕을 내게 만들려면 멋진 무대부터 준비해봐. 그 다음에 생각해볼게.","v":"Idle_01_01","c":0},{"t":"테마파크는 아직 남아있어? 활동 기간이 끝나면 거기서 편안히 지내야 한단말야. 뭐야, 표정이 왜 그래? 부러워?","v":"Idle_01_03","c":0},{"t":"흐응, 뭐야. 여기도 유명했던 애들이 꽤 있잖아? 뭐, 나만큼은 아니지만.","v":"Idle_02_01","c":0},{"t":"테마파크를 부숴버렸다고? 그럼 어서 재건하도록 해. 성의 가장 좋은 방은 당연히 나한테 주고. ...뭐, 특별히 너는 내 바로 옆 방에서 지내게 해줄게.","v":"Idle_03_01","c":0},{"t":"뭐하고 있어? 얼른 시원한 토마토 쥬스를- 어? 화, 화 난 거야? 그렇게 무서운 얼굴로… 꺅?! 자, 잘못했어, 잘못했으니까아… 호, 혼내지 말아주세요...","v":"Idle_04_01","c":0}],"DS_Saraqael":[{"t":"엉망이군. 교단의 천사와 이단심문관도 모자라서, 구원자가 그들과 함께 율법을 어기다니. 바로잡을 필요가 있겠어.","v":"Idle_01_01","c":0},{"t":"네가 예언의 구원자인가… 아니다. 신성한 빛의 예언에 의문을 품다니, 있을 수 없는 일이지.","v":"Idle_01_02","c":0},{"t":"무슨 수단을 써서라도 빛의 뜻과 교단의 정의를 실현하는 것이 내 역할이다. 무력은 여러 수단 중 하나일 뿐.","v":"Idle_01_03","c":0},{"t":"...요청에 따라 그들에 대한 처벌은 보류하겠다. 다만, 기억해라. 교단의 율법은 그 무엇보다 우선한다. 아자젤이나, 구원자인 너도 예외가 아니다.","v":"Idle_02_01","c":0},{"t":"확실히, 네겐 율법을 수정할 권리와 의무가 있다. 그렇다 할지라도, 구원자는 빛의 뜻을 대리할 뿐이라는 것을 잊지 마라.","v":"Idle_03_01","c":0},{"t":"빛의 목소리는 분명 네가 구원자라고 속삭이고 있다. 하지만 이 위화감은 대체… 걱정하지 마라. 그것과 별개로, 네가 올바른 인간이라는 것은 알고 있으니.","v":"Idle_04_01","c":0}],"3P_Hirume":[{"t":"배, 배틀메이드로 쫓겨났다니, 무례한 말을 입에 담는구나. 첩은 그저, 이 강대한 힘을더욱 잘 활용할 수 있는 곳으로 옮겨갔을 뿐이다.","v":"Idle_01_01","c":0},{"t":"그 눈빛은… 네녀석, 첩을 어떻게 할 생각인게냐! 부, 분명 여기저기를 엉망진창으로… 으으… 그것만은...","v":"Idle_01_02","c":0},{"t":"첩은 신성한 광휘를 모시는 무녀. 그대를 지켜- 자, 잠깐! 그렇게 가까이 오지 말거라!","v":"Idle_01_03","c":0},{"t":"그대의 관심 같은 건 첩에겐 필요치 않다. 어차피- 아… 가는 것이냐? 아, 아니다. 그대는 바쁘니까… 첩은 신경쓰지 말고 일 보거라.","v":"Idle_02_01","c":0},{"t":"첩을 상냥하게 대해주겠다고 약조하거라. 그, 그러면… 조금, 아주 조금은 가까이 와도... 괜찮다.","v":"Idle_03_01","c":0},{"t":"정말… 그대여, 벌써 몇 시간째 만지작거리고 있지 않느냐. 그, 꼬리만이면 질릴 수도 있으니, 다른 곳도 쓰다듬어 보거라. 귀라던가, 머리라던가...","v":"Idle_04_01","c":0}],"BR_Hyena":[{"t":"지금부터 샐러맨더랑 한 판 붙으러 갈건데, 너도 같이 갈래? 이번에야말로 따서 그 실실 웃는 얼굴을 납작하게 해줄거라고!","v":"Idle_01_01","c":0},{"t":"돌격과 폭탄은 말이지, 음… 뭐랄까. 그래, 폭발같은 거야. 나는 그것만을 위해 살아가니까!","v":"Idle_01_02","c":0},{"t":"응? 아아, 이 샷건은 그냥 빈손이면 허전해서 드는 거랄까, 뭐랄까… 진짜는 이 폭탄이라고! 한 번 볼래? 자, 엄~청 예쁘지?","v":"Idle_01_03","c":0},{"t":"에이, 또 개털됐네… 야, 사령관. 참치 좀 빌려줄래? 나중에 꼭 따서 갚을게. 응? 응응?","v":"Idle_02_01","c":1},{"t":"야야, 봐봐. 이거 내가 개조한 폭탄인데, 살상 반경이 자그마치 다섯 배라고! 꺄하핫, 대단하지 않아? ...후폭풍? 그런 걸 왜 걱정해?","v":"Idle_03_01","c":0},{"t":"싸울때 조심 좀 하라고? 거리를 두고? 에에, 싫어. 그럴거면 뭐하러 싸워? ...뭐, 네가 그렇게까지 말한다면… 한두발짝 정도는 멀리서 던질게. 됐지?","v":"Idle_04_01","c":0}],"3P_Titania":[{"t":"레아… 그래, 전부 레아 때문이야… 그 가증스러운 여자만 아니었다면 여왕은, 여왕은.... 후후, 죽여버리겠어.","v":"Idle_01_01","c":0},{"t":"여왕을 행복하게 해주겠다고…? ...후후, 후후후후… 아하하하하…! …...너. 정말 마음에 안드네.","v":"Idle_01_02","c":0},{"t":"윽, 머리가… 아윽… 가, 가까이 오지… 마…!","v":"Idle_01_03","c":0},{"t":"왜 자꾸 방해하는 거야? 계속 그런 식으로 레아와 여왕을 떼어놓- 아핫, 그래. 너도 죽고 싶은 거구나?","v":"Idle_02_01","c":0},{"t":"하아, 하아… 후후, 너도 여왕을 비웃고 있는거지? 쓸모없는 폐품이 꼴사납게 발버둥치고 있으니까. ...동정하지 마.","v":"Idle_03_01","c":0},{"t":"그 쓸데없는 고집, 아직도 안 버렸어? ...여왕은 행복 따윈 몰라. 여왕에게 남은 건 오직… 고통과 증오 뿐이야.","v":"Idle_04_01","c":0}],"AGS_Stronghold":[{"t":"장갑판, 이상 무. 핵융합로, 이상 무. 궤도 가동, 확인. 작전수행에 문제 없다는 판단하에 전투대기 중일세.","v":"Idle_01_01","c":0},{"t":"귀하와 나눈 약속대로 1분 1초도 늦지 않았네. 어쩐 일로 본기를 불렀는가?","v":"Idle_01_02","c":0},{"t":"각자 역할이 있듯이, 본기에게도 임무가 있네. 그것이 귀하의 지시이고, 군인은 명령에 따를 뿐.","v":"Idle_01_03","c":0}],"PECS_Muse":[{"t":"♩~ ♬~ ……! 드, 들으신 건가요…? 그냥 별거 아닌 연습곡이에요. 이, 잊어주세요, 프로듀서...","v":"Idle_01_01","c":0},{"t":"무대공포증 때문에 방에만 있다 보니, 사람을 만나는 것도 무서워져서… 저는 그냥 방에 틀어박혀 있는 게 제일 잘 어울려요.","v":"Idle_01_02","c":0},{"t":"방에 있을 땐 작곡을 하거나, 시를 쓰거나… 그… 채, 책도 읽어요. ……! 안돼요...! 비, 빌려드릴 수는 없어요.","v":"Idle_01_03","c":0},{"t":"사실 이 곡은... 제가 가장 소중히 여기는 곡이에요. 미완성이라 어설프지만… 제 진심을, 담았거든요.","v":"Idle_02_01","c":0},{"t":"에…? 이, 읽으신 건가요…? 그걸…? 아, 아아…! 묘사가 좋아서 보기 시작했던 건데… 죄, 죄송해요. 음란한 여자라고 환멸하셨겠죠…?","v":"Idle_03_01","c":0},{"t":"무, 무대에 오르는건, 역시- 정말… 노래로 제 마음을 전할 수 있을까요…? 프로듀서가 말해주면… 용기를 낼 수 있을 것 같아요.","v":"Idle_04_01","c":0}],"PECS_Boryeon":[{"t":"제 성격은 손님분들에게 위협을 주지 않도록, 의도적으로 만들어졌다고 들었어요. 날붙이를 쓰니까요. 헤헷, 근데 저는 그런 건 별로 신경 안 써요.","v":"Idle_01_01","c":0},{"t":"아쿠아 랜드는 종합 건강관리 및 엔터테인먼트 시설이예요. 그중에서 저는 미용이랑 마사지 파트를 담당하고 있구요. 초회는 무료인데, 한 번 받아보시겠어요?","v":"Idle_01_02","c":0},{"t":"앗, 제 취향에 대해 들으신 게 있으신가요? ...오드리 님한테요? 흐음, 어쩔까나아~ 헤헤, 이 쿠폰 다 채우시면 말씀드릴 수 있을지도~?","v":"Idle_01_03","c":0},{"t":"저한테 마사지를 해주신다구요? 아, 아뇨. 남한테 받아보는 건 처음이라… 읏, 으… 이, 이상한 기분이네요...","v":"Idle_04_01","c":0}],"BR_NickyTracy":[{"t":"사랑스러운 가족만 있으면 어디든 내 집이고 고향이지. 우리 토모와 시라유리는 잘 지내고 있어?","v":"Idle_01_01","c":0},{"t":"뛰어난 요원이라고 해도 스트레스는 쌓이기 마련이지. 가끔씩 여가활동으로 해소해 줘야 돼. …취미가, 뭐냐고? 비, 비밀이야.","v":"Idle_01_02","c":0},{"t":"전혀 눈치채지 못했겠지만 사실 난 추리소설이나 영화를 굉장히 좋아해. 의외려나? 눈치챘었어? 사령관, 추리력이 굉장하구나!","v":"Idle_01_03","c":1},{"t":"사령관이랑 붙어 지내서 그런가. 요즘 애들 보기가 힘드네. 같이 보러 갈래? 에이미 언니한테 우리 관계도 보고할 겸 겸사겸사.","v":"Idle_02_01","c":1},{"t":"잠깐! 알 것 같아. 들고 있는 컵떡볶이 2개. 혼자 다 먹으려는 거지? 맞지? 같이 먹자고? 어… 고마워.","v":"Idle_03_01","c":0},{"t":"이제 추리해낸 거야? 맞아. 인적 드문 장소에서 늦은 시간에, 실오라기 하나 없이... 앞으로는 특등석에서 관람하게 해줄게. 그럼 오늘을 즐겨볼까? 사령관.","v":"Idle_04_01","c":1}],"PECS_QueenMane":[{"t":"그 땅꼬맹이들은 잘 지내고 있어? 프라이드의 구성원이 되려면 체력을 길러야 한다고 했는데, 어떻게 성장했을지 궁금한데.","v":"Idle_01_01","c":0},{"t":"전 세계를 아우르는 프라이드는 말도 안된다고? 하. 그렇게 기개가 없어서야... 정 그러면 나한테 잘 배워봐. 노하우를 알려주지.","v":"Idle_01_02","c":0},{"t":"다른 녀석들이 대단하대서 기대했더니… 하. 생각했던 것보다 훨씬 비실비실하잖아? 고작 그 정도로 프라이드를 이끌 수 있겠어?","v":"Idle_01_03","c":0},{"t":"우수한 암컷을 거느리기 위해선, 우선 우수한 수컷이 되어야 되지 않겠어? 특별히 내가 직접 단련시켜주지. 시작은 절벽에서 맨몸으로 뛰어내리는 것부터야.","v":"Idle_02_01","c":0},{"t":"흐음, 뭐야. 옷 아래에 꽤나 멋진 걸 숨겨두고 있었잖아? 섣불리 판단했던 건 사과할게. 그나저나, 그런 대단한 건 좀 더 과시할 필요가 있어. 나처럼 말야.","v":"Idle_03_01","c":0},{"t":"뭐 하는 거야, 사령관. 거대한 프라이드를 거느리는 건 우수한 수컷의 권리이자 의무라고. 어서 다른 녀석들도 네 프라이드에 합류시키러 가자.","v":"Idle_04_01","c":1}],"PECS_Glacias":[{"t":"그대는 보면 볼수록 용살자와 똑 닮았구나. 특히 그 눈. 결연한 의지가 느껴지는 눈동자가 그러하다.","v":"Idle_01_01","c":0},{"t":"모든 게 끝나면… 글쎄. 아무도 모르는 곳에서 혼자 여생을 보내는 것도 나쁘지 않겠지만… 맹우와 함께하는 삶도, 나쁘진 않을 것 같구나.","v":"Idle_01_03","c":0}],"PECS_Mnemosyne":[{"t":"본 개체는 와쳐 오브 네이쳐의 소동물들과 함께할 때, 일종의… 고양감을 느낍니다. 분석 결과, 관리자님에게도 정서상의 안정감을 줄 수 있을 것으로 판단됩니다.","v":"Idle_01_01","c":0},{"t":"본 개체, 므네모시네는 시설의 관리와 유지, 정보의 저장과 처리에 특화되어있습니다. 조속히 사용법에 익숙해지시는 것을 추천드립니다.","v":"Idle_01_02","c":0},{"t":"이야기 상대가 필요하시면 다른 개체를 호출 하겠습니다. ...본 개체와, 말씀이십니까? 그럼 들꽃에 대한 정보를 전달하겠습니다. 몹시, 흥미롭습니다.","v":"Idle_01_03","c":0}],"PECS_Hussar":[{"t":"제가 겪은 것은 아무런 소리도 들리지 않는 우주 공간과, 남아메리카의 가혹한 밀림 뿐입니다. 폐허가 됐기는 하지만, 이렇게 도시화된 곳은 처음이라 조금 설레네요.","v":"Idle_01_02","c":0},{"t":"사투리는 신경쓰지 말아주세요. 제 언어 모듈의 특수성 때문일 뿐이고, 맡은 임무에는 전.혀. 지장 없습니다.","v":"Idle_01_03","c":0},{"t":"사령관님, 뭘 보고 계신가요? ……! 제, 제 전투기록을 어디서…? 그, 그건 전투중에 머리에 피가 몰리면 그게… 어쩔 수 없이 마구 공격하게 돼서요… 하하...","v":"Idle_02_01","c":1},{"t":"와. 사투리 쓰는 바이오로이드 처음 보나 …사람 맘도 모르고. …...진짜가? 내 딱 한번만 더 속아준다. 와, 와 웃는데? 너무 순수하다고? 내가?","v":"Idle_03_01","c":0},{"t":"사령관님, 정찰중에 멀쩡한 카페를 찾았는데 같이 가시겠어요? 날아서 가면 금방이에요. 사령관님이 쓰실 제트팩도 준비했고요. 거기 들렸다가 다른데도 구경 가요.","v":"Idle_04_01","c":1}],"DS_Angel":[{"t":"교단의 천사님들과 수녀님들이 이곳에 다 계셨다니… 빛이시여, 감사드립니다. 교리를 세상에 널리 전할 수 있겠군요.","v":"Idle_01_01","c":0},{"t":"아, 안녕하세요. ...네, 혼자 있었어요. 타인의 감정과 제 감정을 구분할 수 있도록, 하루에 한 번은 혼자만의 시간을 가져야 해요.","v":"Idle_01_02","c":0},{"t":"구원자님을 위해 빛께 기도드리고 있어요. 내일도 빛의 대리인님이 아프지 않게, 다치지 않게 보살펴달라고 간청할게요.","v":"Idle_01_03","c":0},{"t":"요새 저랑 베로니카님만 청소하는 거 같아요. 쓰레기는 생기자마자 바로바로 치워야 하는데… 구원자님께서 직접 천사님들을 타일러주시겠어요?","v":"Idle_02_01","c":0},{"t":"어제도 야근하신 것 같은데 피곤하지 않으세요? 제가 도와드릴 일은 없을까요…? 웃어달라고요? 이, 이렇게 하면 될까요?","v":"Idle_03_01","c":0},{"t":"바쁘지 않으면 제 곁에 있어주실래요, 구원자님? 혼자 있는 것보다 구원자님이 함께 있는 게 더… 마음이, 편안해져요. ...고마워요, 좋아해요...","v":"Idle_04_01","c":0}],"DS_Ramiel":[{"t":"인연이 끊겼던 천사들과 여기서 재회하게 될 줄은 몰랐습니다. 아아… 이 광야에 다시금, 빛의 축복과 영광을…","v":"Idle_01_01","c":0},{"t":"...모두가 구원자님을 위해 헌신하고 기도하는 이유가 있었군요… 빛처럼 밝고 따스한… 경전에 나온 빛의 대리인, 그대로입니다.","v":"Idle_02_01","c":0},{"t":"저를... 가까이 하셔서는 안 됩니다, 구원자님. 저 때문에 구원자님께서 어둠에 물드신다면… 저는...","v":"Idle_03_01","c":0}],"AGS_Arachne":[{"t":"귀함의 전자전 대응 체계를 분석 했습니다. 침입 및 돌파 시뮬레이션을 통한 소프트웨어 업그레이드를 제안합니다.","v":"Idle_01_01","c":0},{"t":"본기의 물리적 무장은 신뢰성이 높으나, 위력적이지는 않습니다. 원래 용도대로만 사용하시기를 권고드립니다.","v":"Idle_01_02","c":0},{"t":"\"거미 여왕\" 인격 검색 중입니다. ...실패. 귀함의 데이터베이스에 해당 사항이 존재하지 않습니다.","v":"Idle_01_03","c":0}],"BR_StratoAngel":[{"t":"나이트 앤젤이요? 후후, 당연히 언니인 제가 더 뛰어나죠. 본인은 절대로 인정 안하겠지만요.","v":"Idle_01_01","c":0},{"t":"오늘도 맘에 없는 말을 해버렸어... 그러려던 게 아닌데... 분명 짜증난다고 생각- 앗. 사, 사령관님?! 후, 후후... 뛰어난 저밖에 못하는 일이 생겼나요?","v":"Idle_01_02","c":1},{"t":"밴시는 항상 제 이야기를 잘 들어줘요. 기특한 레이스는 존경한다고 말해주고요. 하아, 대령님도 조금은 이런 분들을 닮았으면 좋겠는데.","v":"Idle_02_01","c":0}],"BR_JangHwa":[{"t":"아니, 이렇게 한다고 내가 뭐라도 바뀔 거라고 생각해? 착각이 심하시네. 네가 무슨 짓을 해도, 내겐 아무것도 느껴지지 않아.​","v":"Idle_01_02","c":0},{"t":"나는 망해버린 세상을 떠돌면서, 보이는 모든 걸 죽여버리면서 살아왔어. 나를 이해한다고? 네가 나에 대해 뭘 알아.​","v":"Idle_01_03","c":0},{"t":"하, 엄마니 뭐니. 가족 놀이라도 하는 거야? 뭐? 나도 가족이 될 수 있다고? 헛소리 하지 마! 그런 거, 필요 없어...","v":"Idle_02_01","c":0},{"t":"모든 게 사라지고 나서, 나는 목적도 없이 계속 떠돌아다녔어. 그래, 삶의 의미를 찾고 싶어서. ...흥. 내가 이런 이야기를 하다니, 너희들한테 옮았나 보네.​","v":"Idle_03_01","c":0}],"BR_Ellie":[{"t":"저는 귀족 자제분들의 교육도 담당했어요. 예절 교육이 필요한 아이들이 보이던데, 제가 가르쳐도 괜찮을까요?","v":"Idle_01_01","c":0},{"t":"저는 홍차가 정~말 좋아요. 잉글리쉬 브렉퍼스트, 다즐링, 아삼, 실론도 좋지만, 그중에서도 얼그레이가 좋아요. 핫. 방금은 잊어주세요...","v":"Idle_01_02","c":0},{"t":"제가 희생당하기 위해 태어났다는 건, 알고 있어요. 하지만 괜찮아요. 서민을 지키고 봉사하는 것이 제 의무니까요.","v":"Idle_01_03","c":0},{"t":"LRL! 알비스! 복도에서 뛰어다니면 안 된다고 했죠! ...조금은 안드바리 양을 본받았으면 좋겠네요.","v":"Idle_02_01","c":0},{"t":"가끔은 키다리 아저씨를 원했던 적도 있어요. 저를 도와줄 그런 분이요. 마치, 사령관님처럼... 아, 아무것도 아니에요.","v":"Idle_03_01","c":1}],"PECS_Sekhmet":[{"t":"제 자매 세레스티아… 폐하에겐 이모뻘이 되겠군요. …엄마 같다고요? 세레스티아가? 흥. 그런 건 모성이 아닙니다. 앞으로 세레스티아와 만나는 건 삼가주세요.","v":"Idle_01_01","c":0},{"t":"폐하의 기백은 익히 알고 있습니다. 그것을 감당할 수 있는건 오직 저 뿐. 앞으로 폐하의 모든 것은 이 어미가 챙길테니, 그저 마음 편히 계시면 됩니다.","v":"Idle_01_02","c":0},{"t":"자아, 말씀드린대로 다른 대원들과의 대화, 식사, 시중과 폐하의 업무까지- 이 업무는… 조, 조금만 기다리세요. 금방 공부해 오겠습니다.","v":"Idle_01_03","c":0},{"t":"폐하, 아직 일이 끝나지 않았는데 어딜 가시려는 건가요. 이 어미가 분명히- 아, 화장실…? 흠흠. 저도 같이 가겠습니다.","v":"Idle_02_01","c":0}],"PECS_Orangeade":[{"t":"안녕하세요, 신입사원 오렌지에이드예요! 정식으로 오르카 호에서 일하게 됐으니까 남들의 2배, 아니! 10배는 더 열심히 할게요!","v":"Idle_01_01","c":0},{"t":"유들유들한 성격은 현장에서 일하는 사람들에게 필수 소양이죠. 상대방의 경계를 풀고, 쉽게 호감을 쌓을 수 있으니까요. 앗, 무지개다! 대박!","v":"Idle_01_02","c":0},{"t":"화장은 하는 것도 중요하지만 지우는 게 더더더 중요해요. 안 씻고 그냥 자면 피부결이 엉망이 된다구요. 아, 이참에 사령관님도 한번 해보실래요?","v":"Idle_01_03","c":1},{"t":"대박! 사령관님, 이거 보셨어요? 이달의 근태우수자 후보에 제 이름이 올라갔어요! 어디 보자, 일한 시간만 따져보면… 사, 사령관님이 1등?!","v":"Idle_02_01","c":1}],"3P_Amphitrite":[{"t":"사령관님. 혹시 시아 못 보셨나요? 같이 숨바꼭질 중이었는데 도저히 찾을 수가 없어서...","v":"Idle_02_01","c":1}],"3P_Salacia":[{"t":"엠피 언니가 아무한테나 '방긋방긋' 하지 말래. 전단장님은 '방긋방긋' 좋아? 시아는 엄~청 좋아. 에헤헤, 방긋방긋~","v":"Idle_01_01","c":0},{"t":"시아, 혼자서도 잘 해. 밥 먹고 양치하는거랑, 세수하는거랑, 옷도... 사실 옷은 잘 못입어. 시아 나갈 때 입는 옷, 입기 너무 어려워...","v":"Idle_01_03","c":0},{"t":"전단장님, 시아 숨겨줘! 엠피 언니가 잡으러 온단말이야! 응? 빨리빨리!","v":"Idle_02_01","c":0},{"t":"간지러워어~ 시아 만지는 거 재밌어? 시아도 할래. 와아, 이상한 느낌… 남자는 원래 이래?","v":"Idle_03_01","c":0},{"t":"시아는 전단장님이 엄~청 좋아. 엄~청이 얼마만큼이냐구...? 으… 얼마만큼, 얼마만큼... 모르겠어. 그냥 엄~청 좋은데, 그러면 안 돼...?​","v":"Idle_04_01","c":0}],"3P_Frigga":[{"t":"저는 가디언의 방패로써, 주인님과 자매들을 지켜왔어요. 만약 주인님이나 자매들에게 무슨 일이 생긴다면... 분노에 눈이 멀기도 하죠.​","v":"Idle_01_01","c":1},{"t":"주인님, 잠시... 불편하지는 않으신가요? 저는 누군가를 끌어안을 때가 정말 좋아요. 조금만 더 이렇게...​","v":"Idle_01_02","c":1},{"t":"저는 단지 누군가를 보살펴주고 사랑해주는 것을 좋아할 뿐이에요. 어쩌면 엄마처럼 행동하고 싶은 것일 수도...​","v":"Idle_01_03","c":0},{"t":"가디언 자매들도, 컴패니언 자매들도 제가 안아주면 잘 받아주는데 유독 포이만 도망치더라구요. 저는 그냥 너무 기뻐서 조금 힘을 줬을 뿐인데...​","v":"Idle_02_01","c":0},{"t":"어머, 어리광을 부리시는 건가요? 주인님이 원하신다면 언제든지 괜찮아요. 주인님, 정말... 아이 같아요.​​","v":"Idle_03_01","c":1},{"t":"제가 포옹을 좋아하는 이유는, 이렇게 꼭 안고 있으면, 주인님이 제 곁을 떠나지 않을 것만 같아서 그래요. 항상 제 곁에 있어줄 것만 같은 그런 기분이요...​","v":"Idle_04_01","c":1}],"ST_Ullr":[{"t":"어, 어디 가는 거야? 가지 마...세요. 저를 혼자 두지 마세요. 제발제발제발… 부탁이에요. 화장실이요? 그, 그건… …앞까지만이라도 같이 갈래요…​","v":"Idle_01_02","c":0},{"t":"으음… 사령관 거기 있어? 실루엣 정도는 보이지만, 가까운 건 잘 안 보인단 말이야. 그렇다고 멀리 떨어져 있을 수도 없구. 안경이라도 맞춰야 할까?​","v":"Idle_01_03","c":1},{"t":"얘들아. 그렇게 사령관의 곁에서… 어, 어쩔 수 없네… 나도 같이 있어줄게. 응? 뇌파? 무, 무슨 소리인지 잘 모르겠는데?​","v":"Idle_02_01","c":1},{"t":"오늘도 사령관을 껴안고 자도 돼? 나는 뭔가를 안고 있지 않으면 잠에 들지 못하니까… 그리고 사령관이랑 있으면 마음이 편안해지는 것도 있구…​","v":"Idle_04_01","c":1}],"BR_Cheona":[{"t":"야, 핫팩. 내 혀가 그렇게 신경쓰여? 말 돌리지 말고. ...어떻게 움직이는지 한 번 볼래? 손 이리 줘봐.","v":"Idle_01_03","c":0}],"PECS_Peregrinus":[{"t":"한 번 겨뤄보고 싶은데, 여기서 가장 빠른 녀석은 누구지? 자신있냐고? 물론! 나같은 하피에게 기동력은 중대사항이거든. 내가 괜히 하피의 왕이겠어?","v":"Idle_01_01","c":0},{"t":"용살자? 흐음… 용살자는 신중하지만 현명하게 싸울 줄 알고, 동료를 소중하게 여기며, 부드러우면서도 강인하게 우리를 이끌어주던 녀석이었지. 그래, 마치 너처럼.","v":"Idle_01_02","c":0}],"PECS_CyclopsePrincess":[{"t":"감히 짐의 이름을 참칭하는 녀석이 있다고 하던데… 그녀석을 당장 대령하거라. 그 뻔뻔한 얼굴을 한 번 보고싶구나.","v":"Idle_01_01","c":0},{"t":"그래... 죽음조차도 이 진조의 공주를 막지 못한게지. 후후후… 자아, 용살자여. 시공을 넘어 다시 한 번 짐을 섬기는 영광을 내리겠노라!","v":"Idle_01_02","c":0},{"t":"죽음을 극복하며 다시 이모습이 되고 말았나… 흐릿하지만 기억은 남아있으니, 여전히 용살자와 함께 싸울 수 있겠지.","v":"Idle_01_03","c":0},{"t":"아아, 그 아이 말이더냐. 짐에게 진심어린 경의를 표하기에 눈감아 주었지. 후후후, 눈감아주었을 뿐이겠느냐! 이 몸께서 직접 큰 상을 내렸노라!","v":"Idle_02_01","c":0}],"DS_BunnySlayer":[{"t":"바니걸... 눈에 담지도 못할 역겨운 녀석들이야. 그래... 죽이지 않을 이유가 없다!​","v":"Idle_01_01","c":0},{"t":"니히힛. 네 소중한 바니걸들은 이미 하나하나 역바니가 되어가고 있다. 이쯤하고 항복하시지, 사악한 바니 대왕 씨! 물론 자비를 베풀지는 않을 거지만!​","v":"Idle_01_03","c":0}],"BR_Habetrot":[{"t":"스, 승리! 스틸라인 부대의 소위, 하베트롯입니다. 모쪼록 많은 지도 편달 부탁드리겠습니... 아니, 부탁이 아니라! 간부로서 책임감을 갖고 열심히 하겠습니다!​","v":"Idle_01_01","c":0},{"t":"이게 중요하면서 급한 업무고, 저게... 앗, 사령관님! 오셨습니까. 업무가 익숙해질 때까지만 추가 근무하려구요. 이러면 금방 실력이 늘겠죠.​","v":"Idle_01_02","c":1}],"ST_Mercury":[{"t":"오호호! 갖고 싶은 걸 물어봐 주시는 건 감사하지만 본녀는 완전무결! 더 이상 바라는 건 없사와요. 굳이 부탁드리자면 친우들과 나눠먹을 간식 정도?​","v":"Idle_01_02","c":0},{"t":"여기, 선물이에요. 이번 임무에서 발견한 사슴벌레죠. 오호호! 고마워하지 않으셔도- 또 잘못된 정보라구요? 이, 이번엔 분명히 혈액순환에 좋다고 들었는데...!​","v":"Idle_01_03","c":0},{"t":"도움이 필요하면 언제든 본녀를 불러주시길. 다른 분들에게 보탬이 되는 건 기쁜 일이니까요. 특히나 사령관한테는 더더욱이요. 오호호호!​","v":"Idle_02_01","c":1}],"BR_Scarabya":[{"t":"안녕. 나는 앵거 오브 호드의 기술 고문을 담당하고 있어. 자세한 직책은... 음... 뭔지 알겠지?​","v":"Idle_01_01","c":0},{"t":"또 같은 항의네. 난 미리 얘기했어. 개조하면 외형이 \"조금\" 변할 수 있다고. 총알만 발사되면 총인 건 변하지 않잖아.​","v":"Idle_01_02","c":0}],"3P_Melite":[{"t":"내 이름은 멜리테, 초코랜드의 여왕이다! 초코랜드가 진짜 있냐고? 흥. 내가 바로 초코랜드 그 자체인 것을. 즉, 내가 있는 한 초코랜드 왕국 또한 실존한다!​","v":"Idle_01_01","c":0},{"t":"나라를 세우기 위해선 광활한 영토가 필요하지... 그래! 눈에 보이는 모든 걸 점령하고, 점령하고, 또 점령하는 것이다!​","v":"Idle_01_02","c":0},{"t":"오늘은 아침부터 몹시 기분이 좋군. 좋아, 축제다! 돈은 걱정하지 않아도 되니 최고로 화려하게, 거창하게 여는 것이다!​","v":"Idle_01_03","c":0}],"PECS_Sonia":[{"t":"의욕이 넘치는 건 좋은데... 보스, 저번에 다수결로 법 바뀐 거 기억하지? 이젠 과로도 불법이야. 한 번은 경고로 넘어가겠는데 다음엔 체포할 거야. 알았어?​","v":"Idle_01_02","c":0},{"t":"잘못을 했으면 법에 따라 처벌받아야지. 치안은 걱정하지 마, 보스. 내가 있는 한, 누구도 위법 행위를 저지르게 두지 않겠어.​","v":"Idle_01_03","c":0}],"3P_Ajax":[{"t":"프리가 언니는 동생인 제가 봐도 뛰어나지만, 자꾸 절 어린애 취급하셔서... 조금, 대하기 까다롭습니다. 동료로 인정받을 때까지 노력해야겠죠.​","v":"Idle_02_01","c":0}],"PECS_Erato":[{"t":"쉴 때도 밖에서 팬들 만나는 게 좋아. 그 자리에서 노래도 하고, 팬미팅도 갖고... 상상만 해도 힘이 나네. 팬들의 관심과 애정이 날 움직이는 원동력이야!​","v":"Idle_01_02","c":0},{"t":"여기! 약소하지만 정성껏 준비한 선물이야. 나는 팬분들이 챙겨주지만, 프로듀서는 내가 안 챙기면 누가 챙겨주겠어. ...어때? 마음에 들어?​","v":"Idle_03_01","c":0}],"BR_Brunhild":[{"t":"내가 겪은 일이 궁금해? 글쎄, 썩 유쾌한 이야기는 아닐 텐데. 다른 애들한테 어떤 꼴을 겪었는지 못 들어봤나 봐? ...비싼 실험쥐에 빗대면 알아 듣겠어?​","v":"Idle_01_01","c":0},{"t":"자주 찾아와줘서 미안한데, 지금은 내가 좀 바빠서. 다음에 다시 와주겠어? 뭐... 그땐 또 다른 일이 생길 것 같지만.​","v":"Idle_01_02","c":0},{"t":"스스럼없이 말 거는 게 당신 장점이지. 멸망 전에도 비슷한 인간이 있었어. 상대가 누구든 속알맹이 없는 소리만 늘어놓던 녀석인데... 당신은 다르겠지?​","v":"Idle_01_03","c":1},{"t":"돈이 썩어나는 놈들에게 돈으로 해결할 수 있는 건 문제가 안 되지. 험하게 다뤄 부서져도 다시 만들면 그만인 소모품… 이해됐어? 그게 버뮤다팀 애들이야.​","v":"Idle_02_01","c":0},{"t":"연구소에 당신과 비슷한 인간이 있었어. 나한테 필요한 건 없냐느니, 남편을 찾았다느니 호들갑 떨던 애인데… 생각나서 해본 얘기야. 특별한 의미는 없어.​","v":"Idle_03_01","c":1}],"BR_Kheshig":[{"t":"저는 병참 관리와 부상병 구호를 담당했어요. 전선에 서는 동포의 생존율을 1%라도 높이 향상시켜, 임무에 전념할 수 있도록 서포트하는 게 제 역할이랍니다.","v":"Idle_01_01","c":0},{"t":"아, 사령관님… 아뇨, 아직 익숙하지 않은 일들이라 조금 피곤했나 봐요. 금방 익숙해질 거니까, 걱정하지 않으셔도 돼요. 금방 익숙해질 거니까...","v":"Idle_01_02","c":1},{"t":"저... 왠지, 아까부터 저쪽의 미녀분께서 노려보셔서... 혹시 제가 잘못한 게 있을까요? 저도 모르는 사이에 실례라도 저지른 건...!","v":"Idle_01_03","c":0}],"BR_Vargr":[{"t":"나는 여제님의 사냥개다. 여제님의 명에 따라 목표를 파괴하고, 적을 멸절했다. 또한 배신자들의 처형도 맡았지. 그러고보니… 낯익은 얼굴이 보이더군.​","v":"Idle_01_01","c":0},{"t":"흐트러진 것은 싫다. 바르지 못한 것도 싫다. 모두가 나처럼 사는 것까지는 바라지 않지만, 규칙을 어긴 자를 훈계하는 건 용납해 주길 바란다.​","v":"Idle_01_02","c":0},{"t":"이곳은 군기가 지나치게 해이해져 있더군. 나에게 명령권을 주면 군기를 바로잡겠다. 우선은 손무와 팽월을 본 받아 몇 명의 목을 베겠다.​","v":"Idle_02_01","c":0},{"t":"라비아타, 레모네이드 알파, 무적의 용… 이들이 왜 너를 따르는 지는 아직 모르겠다. 단순히 인간이라서 따를 이들이 아닌데… 너를 좀 더 지켜보겠다.​","v":"Idle_03_01","c":0},{"t":"요즘 자주 마주치는 거 같다고? 기분탓 아닌가? 이왕 마주친 김에 묻는데… 동행해도 되겠나? 이유? …잠시만 기다려 줄 수 있나? 지금 생각해보겠다. ​","v":"Idle_04_01","c":0}]};
